insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 1, 'On the EKPAN lottery at a success probability of 0.350000, weighting each action''s column by the priors and then taking the largest gives 75.7500. What does taking the largest value in each outcome first, and weighting second, give?', '["52.0000 directly, because weighting the per-outcome maxima already subtracts the lottery''s prior decision inside the sum.", "365.0000, the lottery''s Drill net on Success, because learning the outcome first raises the chance of success to 1.", "127.7500, the value of deciding after the outcome is announced, which is evWithPerfect on the lottery and not yet the worth of the information.", "75.7500 again on the lottery, since the same six numbers go in and the order of a maximum and a weighted sum cannot change a result."]'::jsonb, 2, 'The order of the two operations is the whole method: on the EKPAN lottery 0.350000 x 365.0000 + 0.650000 x 0.0000 = 127.7500, and only its excess over 75.7500, 52.0000, is the value of the information.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 2, 'A reader computes EVPI on the EKPAN lottery as 127.7500 less the farm-out''s 33.2500, reasoning that perfect information sometimes recommends the farm-out. What is wrong with the baseline?', '["It credits the information with Drill''s advantage over Farm out, which the company already holds without it; the baseline is the prior best action, Drill at 75.7500 on the lottery.", "Nothing, since EVPI measures the gain over the action that perfect information would replace, and on the lottery''s Dry hole that action is the farm-out.", "The farm-out value must first be taken net of the lottery''s drill cost of 55.0000, because a cost is paid under every action once it is on the tree.", "It should subtract Walk away at 0.0000, since information is always measured against doing nothing at all."]'::jsonb, 0, 'EVPI on the EKPAN lottery subtracts the best decision available today, 75.7500, giving 52.0000; subtracting 33.2500 overstates it by Drill''s lead over Farm out at the prior.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 3, 'Why is EVPI on the EKPAN lottery at 0.350000 equal to 0.650000 x 80.0000?', '["EVPI is the expected loss of the Drill action on the lottery, the dry hole loss weighted by its chance, whatever the other actions happen to pay in that outcome.", "On Success perfect information switches the lottery from Drill to Farm out, and the 80.0000 is the net difference between them weighted by the dry hole chance.", "The lottery''s farm-out forgoes 95.0000 on Success and Drill avoids 80.0000 on Dry hole, and on this lottery only the second term survives the weighting.", "Perfect information changes the prior choice only on Dry hole, from Drill at -80.0000 to 0.0000, and that gain is weighted by how often the dry hole occurs."]'::jsonb, 3, 'EVPI on the EKPAN lottery is the expected regret of the prior choice: on Success Drill stays best at 365.0000, so the only gain is 80.0000 on the dry hole, 0.650000 x 80.0000 = 52.0000.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 4, 'On the EKPAN lottery''s Dry hole row the engine reports Farm out as the best action if known, beside a best value of 0.0000. What would listing Walk away before Farm out change?', '["Nothing at all, because the engine breaks a tie by the larger payoff in the other outcome, where the lottery''s Farm out pays 95.0000 against 0.0000.", "Only the name reported for Dry hole, which becomes Walk away; the best value 0.0000 and evWithPerfect 127.7500 on the lottery stay the same.", "evWithPerfect on the lottery, because Walk away is valued as a terminal and Farm out as a chance node, so the rollback reaches a different expectation.", "The prior decision, because listing order is also the order in which the engine weights the lottery''s actions at 0.350000."]'::jsonb, 1, 'Farm out and Walk away both pay 0.0000 on the EKPAN lottery''s dry hole and the engine keeps the first branch listed; EVPI takes the best VALUE per outcome, so 52.0000 does not depend on the label.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 5, 'dominantAction has outcomes at 0.300000 and 0.700000, and its better action pays 100.0000 or 50.0000, yet its EVPI is 0.0000. Why?', '["Its payoff swing is too small beside its prior EMV of 65.0000 for the engine to register any value of knowing the outcome.", "The same action is best in both outcomes, so knowing which one arrives would never change what is done.", "Its actions carry no cost, and EVPI is measured only against the money that a costed action puts at risk in a bad outcome.", "The engine refuses to value information on a lottery with no losing outcome, and returns 0.0000 in place of an answer."]'::jsonb, 1, 'Always pays 100.0000 against 10.0000 and 50.0000 against 5.0000, so the maximum in each outcome picks Always and weighting returns 65.0000 on both sides; the size of the swing never enters the test.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 6, 'A spreadsheet reports a negative EVPI on a lottery. What does that say?', '["The prior action is so good that learning the outcome would tempt the company away from it, a real cost of knowing in advance that the engine subtracts from evWithPerfect.", "The information would arrive too late to act on, and the engine charges the delay against the value of knowing as a negative amount.", "The inputs or the arithmetic are wrong, since in every outcome the best value is at least the prior action''s value, and weighting cannot reverse that.", "A risk averse utility function has pulled the value of knowing below zero for a company that dislikes seeing the bad outcome early."]'::jsonb, 2, 'evWithPerfect can never be less than emvPrior, so an EVPI below 0.0000 is an error; the engine is risk neutral and undiscounted, with no utility function and no delay to charge.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 7, 'certainOutcome returns an EVPI of 0.0000, with emvPrior and evWithPerfect both 260.0000. A contractor offers a cheap survey on that decision. What is the survey worth on EMV grounds?', '["Nothing, because imperfect information is bounded by perfect information, so no survey on that decision can be worth more than 0.0000.", "Up to the prior value of 260.0000, since a certain outcome makes every reading of the survey certain to be correct.", "Anything below the drill cost of 40.0000, since the survey only has to beat the capital it protects to be worth buying.", "It cannot be said until the survey''s likelihoods are known, since EVPI bounds only perfect information and not a real survey."]'::jsonb, 0, 'When one outcome has probability 1.000000 there is nothing to reveal; a zero EVPI closes the question for every kind of information on the decision, and the right price is nothing.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 8, 'The EKPAN lottery''s EVPI sweep reads 54.0000 at 0.200000 and 60.0000 at 0.250000. Where does EVPI peak, and why there?', '["At 0.250000 and 60.0000, the largest row of the lottery sweep, since EVPI rises smoothly between rows and the sampled rows are close enough together to find it.", "At 0.500000 on the lottery, where Success and Dry hole are equally likely and uncertainty about the outcome is therefore greatest.", "Midway between 0.200000 and 0.250000, where the two sampled lottery values would meet if the rows were joined by one straight line.", "At 0.228571, where Drill and Farm out are both worth 21.7143 on the lottery, giving 61.7143, because the prior decision is least settled there."]'::jsonb, 3, 'The peak on the EKPAN lottery sits at the drill against farm-out switch, 80 / 350 = 0.228571, where 83.4286 less 21.7143 is 61.7143; at 0.500000 EVPI is only 40.0000.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 9, 'At 0.228571 the engine names Farm out as the prior best action on the EKPAN lottery, with both actions printed at 21.7143. What decides that name?', '["The tie rule, which keeps the first action listed when a later one is only equal, and so names the farm-out whenever the two lottery values print alike.", "A built-in preference for the action that never loses money when two lottery EMVs agree to four decimals.", "Floating point residue: 80 / 350 has no exact binary image, and Drill comes out below Farm out in the last binary digits.", "EVPI, which is 61.7143 under Farm out and lower under Drill, so the engine names the lottery action that leaves the most to learn."]'::jsonb, 2, 'Drill is listed before Farm out on the EKPAN lottery, so the tie rule would name Drill; Drill less Farm out is -7.11e-15 there, and EVPI of 61.7143 is the same whichever is named.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 10, 'On the EKPAN lottery at a success probability of 0.050000, EVPI is 13.5000. In which outcome does perfect information change the prior action?', '["Dry hole, where the lottery''s Drill at -80.0000 gives way to 0.0000, exactly as it does at the stated prior of 0.350000.", "Success, where the prior best Farm out gives way to Drill''s 365.0000 against 95.0000 on the lottery.", "Both outcomes, since at a low success chance Walk away is the lottery''s prior best action and each outcome favours something else.", "Neither, since 13.5000 is the value of confirming the lottery''s prior action rather than of changing it in some outcome."]'::jsonb, 1, 'Left of the switch the EKPAN lottery''s prior best is Farm out, so the only gain is on Success: 0.050000 x (365.0000 less 95.0000) = 13.5000. Walk away is never best on the lottery above 0.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 11, 'A reader builds the EKPAN lottery''s perfect-information table from the gross Drill payoffs, 420.0000 and -25.0000, instead of the net ones. What survives the error?', '["The best action in each outcome survives and the value does not, because 420.0000 enters the weighting where 365.0000 belongs.", "Both survive, because the lottery''s drill cost of 55.0000 is paid in every outcome and so cancels out of evWithPerfect.", "Neither survives, because -25.0000 now beats 0.0000 on Dry hole and Drill becomes best in both outcomes.", "The value survives and the action does not, since a cost matters only when two actions are compared within an outcome."]'::jsonb, 0, 'On the EKPAN lottery Drill still wins Success and still loses Dry hole (-25.0000 is below 0.0000), but Drill enters evWithPerfect only on Success, so its 55.0000 cost does not cancel.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 12, 'The published prospect and voiDefaultLottery both reach evWithPerfect 78.0000, yet their EVPIs are 35.0000 and 63.0000. What separates them?', '["Their success chances, since voiDefaultLottery''s lower prior leaves more of the outcome still to be revealed by the information.", "voiDefaultLottery reports its EVPI gross of the drill cost of 40.0000 and the prospect reports it net of that cost.", "voiDefaultLottery''s dry hole payoff of -50.0000 enters evWithPerfect, and the 78.0000 printed for it rounds that difference away.", "The decision without information: the prospect''s prior best is worth 43.0000 and voiDefaultLottery''s 15.0000."]'::jsonb, 3, 'Both run a success chance of 0.300000; the prospect''s farm-out raises its prior decision to 43.0000, leaving 35.0000 to gain, while 15.0000 leaves 63.0000. The -50.0000 never enters, since nobody drills a known dry hole.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 13, 'On the EKPAN lottery at 0.350000 a vendor prices a study of the prospect above 52.0000. What can be said before any Bayes is done?', '["The price can be refused, since no information about this decision can be worth more than its EVPI of 52.0000.", "Nothing yet, since an accurate enough study could be worth up to the lottery''s evWithPerfect of 127.7500.", "It is acceptable if the study''s hit rate beats the lottery''s prior of 0.350000, since EVPI caps only weak studies.", "It should be compared with the lottery''s drill value of 75.7500, the most that any study of it could protect."]'::jsonb, 0, 'EVPI caps every survey on the EKPAN lottery decision; the CSEM survey there is worth 24.8250, inside the 52.0000 ceiling, and a value above it is an error in the inputs or the arithmetic.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 14, 'At a success probability of 0.900000 the EKPAN lottery''s EVPI is 8.0000. What does that small number say about drilling?', '["Drilling is close to risk free there, since EVPI is the expected loss the company is exposed to by drilling the lottery.", "Farm out has become the lottery''s prior best action, and perfect information would switch to Drill only on Success.", "The prior choice of Drill is rarely wrong there; Drill still loses 80.0000 on the lottery whenever the dry hole comes.", "The engine floors EVPI near the lottery''s drill economics, so 8.0000 is a lower limit and not a computed value at all."]'::jsonb, 2, 'On the EKPAN lottery 0.100000 x 80.0000 = 8.0000: the dry hole is rare, so the choice is rarely wrong, but a risk neutral EVPI says nothing about the size of the loss when it happens.'),
  ('decision', 'intermediate', 'module', 'm01-perfect-information', 15, 'A careful reader values the EKPAN lottery with perfect information at 365.0000, pricing the prospect as if success were certain. What is the error?', '["The figure is the right evWithPerfect for the lottery but has to be reduced by the drill cost of 55.0000 once more before it is quoted, since the table shows outcomes and not branches.", "It should be the EKPAN tree''s 105.0000, since perfect information restores the marginal find the lottery folded away.", "The sign is wrong: perfect information lowers the lottery''s success value to the farm-out''s 95.0000, because a known success is sold for its farm-out price.", "Knowing the outcome does not change how often it occurs: the lottery is still dry 0.650000 of the time, so evWithPerfect is 127.7500."]'::jsonb, 3, 'Perfect information on the EKPAN lottery announces Success 0.350000 of the time, exactly as often as it arrives. The 105.0000 belongs to the EKPAN TREE, a different three-outcome model, and mixing the two is the error that distractor examines.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 1, 'The EKPAN lottery survey''s Bright spot row reads 0.850000 given Success and 0.250000 given Dry hole, which sum to more than 1. Is that an error?', '["Yes, and the engine refuses it, because a row of likelihoods is the chance of that reading across every outcome and must be a distribution.", "No: each column is a distribution over readings for one outcome, and a row answers no single question, so nothing requires it to sum to 1.", "Yes, and the engine rescales the row to 1 before Bayes, which is why the lottery''s posterior after a bright spot comes out at 0.646739.", "No, because likelihoods are grades of the survey''s accuracy, and only their average across the row has to stay below 1."]'::jsonb, 1, 'On the EKPAN lottery survey 0.850000 and 0.150000 sum to 1 given Success, and 0.250000 and 0.750000 given Dry hole; those columns are what the engine checks.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 2, 'A likelihood column for Success is typed so that it sums to 0.900000. What does the engine do with it?', '["Rescales the column in proportion so that it sums to 1, values the survey on the corrected likelihoods and flags nothing to the user.", "Accepts it, since the tolerance allowed on a likelihood column is looser than the 1e-6 allowed on the probabilities at a chance node.", "Assigns the missing 0.100000 to a reading of its own, as if the survey returned no reading at all on that share of successes.", "Refuses it, with a message naming the Success column and the sum 0.900000, and rescales nothing."]'::jsonb, 3, 'The published likelihoodColumnBelowOne case is refused: "Likelihoods P(signal | "Success") sum to 0.900000, expected 1". A column that misses 1 is never quietly normalised.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 3, 'What is the chance of a bright spot before the EKPAN lottery survey is shot?', '["0.460000, the prior-weighted sum of 0.297500 from successes and 0.162500 from dry holes.", "0.850000, the lottery''s hit rate, as if only successes lit up.", "0.550000, half the lottery''s likelihood row sum, one equal weight per outcome.", "0.350000 on the lottery, the prior, since a survey cannot change how often the prospect succeeds or how often it lights up."]'::jsonb, 0, 'On the EKPAN lottery 0.350000 x 0.850000 = 0.297500 and 0.650000 x 0.250000 = 0.162500, together 0.460000. The hit rate counts only successes, and equal halves ignore how often each outcome occurs.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 4, 'Of the EKPAN lottery''s 0.460000 chance of a bright spot, 0.162500 comes from dry holes. Why does a false alarm rate of only 0.250000 contribute that much?', '["The lottery''s false alarm rate is added to the miss rate of 0.150000 before it is weighted, and that addition inflates the dry share of bright spots.", "Dry holes are counted twice on the lottery, once in the bright spot row and once in the no bright spot row, before the joint chances are summed.", "It applies to the dry outcomes, which are 0.650000 of the prior, a much larger base than the 0.350000 of successes.", "The hit rate 0.850000 shrinks once divided by the lottery''s prior, so the dry share only looks large beside it."]'::jsonb, 2, 'Each joint cell on the EKPAN lottery is prior times likelihood: 0.650000 x 0.250000 = 0.162500. That share of bright spots is what keeps a bright spot from settling the question.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 5, 'A reader divides the EKPAN lottery joint chance 0.297500 by the prior 0.350000 and gets 0.850000. What went wrong?', '["The posterior divides the joint by the chance of the reading, 0.460000, giving 0.646739; dividing by the prior returns the likelihood the calculation started from.", "Nothing went wrong: the hit rate and the lottery''s posterior coincide whenever the joint chance is taken with the success outcome rather than the dry one.", "The joint should first be multiplied by the lottery''s pSignal of 0.460000 and only then divided by the prior 0.350000.", "The divisor should be the lottery''s dry hole prior of 0.650000, since a posterior compares the reading with the alternative outcome."]'::jsonb, 0, 'Bayes on the EKPAN lottery is joint over pSignal: 0.297500 / 0.460000 = 0.646739. A reader who finishes holding the hit rate has divided by the wrong number.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 6, 'Weight the EKPAN lottery''s success posteriors, 0.646739 and 0.097222, by the signal chances 0.460000 and 0.540000. What comes back, and what does it mean?', '["A number above the lottery''s prior of 0.350000, because a survey with a hit rate of 0.850000 raises the expected chance of success of the prospect it reads.", "The prior 0.350000: a survey moves belief up on one reading and down on the other and in expectation moves it nowhere, so its value comes only from fitting the action to the reading.", "Nothing meaningful, because posteriors taken after two different readings describe two different prospects and cannot be combined into one probability.", "The average of the lottery''s two likelihoods, because weighting by the signal chances undoes the Bayes division."]'::jsonb, 1, 'On the EKPAN lottery 0.460000 x 0.646739 + 0.540000 x 0.097222 returns 0.350000. Because every posterior is derived from one prior, the engine guarantees that average.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 7, 'Reading the EKPAN lottery likelihood 0.850000 as the chance of success after a bright spot, what is Drill worth after a bright spot, and which way does the error push?', '["207.7989 either way, because Drill is still the lottery''s best action after a bright spot and its value is read from the tree rather than from the probability.", "262.7989, the lottery''s drill chance node, because 0.850000 enters the weighting before the drill cost of 55.0000 and never meets it.", "An understatement on the lottery, because 0.850000 leaves out the prior of 0.350000, which the posterior adds on top of the hit rate.", "298.2500 against the posterior''s 207.7989, an overstatement on the reading that argues for drilling."]'::jsonb, 3, 'The engine at probability 0.85 gives the EKPAN lottery''s Drill 298.2500; at the posterior 0.646739 it is 207.7989. The error pushes the decision the way a hopeful team already leans.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 8, 'After no bright spot on the EKPAN lottery, a reader compares the drill chance node at 18.2639 with Farm out at 9.2361 and drills. What is the right comparison?', '["The same comparison is right, since the lottery''s drill cost was already paid when the survey was bought and cannot be charged twice.", "Drill at 18.2639 against Walk away at 0.0000, since the lottery''s farm-out is withdrawn by a partner once a negative reading is known.", "The drill branch after its 55.0000 cost, -36.7361, against 9.2361, which makes Farm out best.", "The lottery''s prior drill value of 75.7500 against 9.2361, since a survey changes the probabilities and never the drill economics."]'::jsonb, 2, 'Subtract every branch cost before taking a maximum: on the EKPAN lottery 18.2639 less 55.0000 is -36.7361. Node values give the right action after a bright spot and the wrong one here.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 9, 'What makes the EKPAN lottery survey worth anything at all?', '["Its hit rate of 0.850000 exceeds the lottery''s prior of 0.350000, so each of its readings adds knowledge about the prospect and knowledge is worth money.", "Its success posteriors, 0.646739 and 0.097222, straddle the lottery''s switch at 0.228571, so the two readings lead to different actions.", "It raises the chance of success after a bright spot, which lifts the expected chance of success of the lottery above 0.350000.", "Its posteriors differ from the lottery''s prior, and any movement in belief carries value in proportion to its size, whichever action follows."]'::jsonb, 1, 'If both readings led to Drill the survey would be worth nothing. On the EKPAN lottery a posterior above 0.228571 favours Drill and one below favours Farm out.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 10, 'On which reading does the EKPAN lottery survey earn its value, and what does the action change from there?', '["No bright spot, where Farm out at 9.2361 replaces a Drill branch worth -36.7361; after a bright spot the prior action is kept.", "Bright spot, where the lottery''s Drill value rises from 75.7500 to 207.7989 and that whole rise, weighted by 0.460000, is credited to the survey.", "Both readings, weighted by 0.460000 and 0.540000, since each reading moves the lottery''s posterior away from 0.350000.", "Bright spot, because 0.646739 is above the lottery''s switch and confirms Drill with more confidence than the prior did."]'::jsonb, 0, 'On the EKPAN lottery the only gain is on no bright spot: 0.540000 times the switch from -36.7361 to 9.2361 recovers the whole 24.8250 of EVII.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 11, 'What is the expected value of imperfect information for the EKPAN lottery survey?', '["100.5750 on the lottery, the value of deciding after the reading, since that is what the company holds once the survey is in.", "52.0000 on the lottery, since a survey with a hit rate of 0.850000 recovers the whole perfect information ceiling on the reading that matters.", "16.8250 on the lottery, since a value of information is always quoted after the survey''s cost of 8.0000 has been paid.", "24.8250, evWithInfo 100.5750 less emvPrior 75.7500."]'::jsonb, 3, 'On the EKPAN lottery EVII = 0.460000 x 207.7989 + 0.540000 x 9.2361 less 75.7500 = 24.8250, gross of any price and inside 0 and the EVPI of 52.0000.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 12, 'Before the repair, the VOI Analyzer printed a gross value of information of -15.00 for typed indicator numbers. What does the lower bound on EVII say about that card, and what does the repaired Analyzer do?', '["The survey was harmful: acting on its readings lost 15.00 against the prior decision, and the repaired Analyzer reports the loss as a negative card.", "The repaired Analyzer clamps the value to 0.00, which is the lower bound applied as a floor on whatever the typed numbers produce.", "Information derived by Bayes can never be worth less than 0, so the typed numbers contradicted each other; the repaired Analyzer withholds that value.", "The negative figure was net of the survey cost, and the repaired Analyzer now splits it into a gross card and a net card."]'::jsonb, 2, 'A company holding a survey can always ignore it, so EVII cannot be negative. The -15.00 card is history from before the repair; the Analyzer now keeps EMV without information and EVPI and withholds the rest.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 13, 'The published perfectSignal case returns an evii of 35.0000. Why is that the most any survey on its prospect can return?', '["Its posteriors are 1.000000 and 0.000000, so it never misreads, and 35.0000 equals that prospect''s EVPI, the ceiling for every survey on it.", "The engine clamps evWithInfo at 78.0000 as a safety limit, and the clamp happened to bind on this survey and not on the others.", "Its two readings are equally likely, 0.500000 each, and an evenly split survey is the most informative one that a two-outcome prospect allows its readings to be.", "35.0000 is the price cap written into the golden so that the net value of the survey stays at or above zero."]'::jsonb, 0, 'perfectSignal''s evWithInfo of 78.0000 is the published prospect''s evWithPerfect, and 78.0000 less 43.0000 is 35.0000. Nothing is clamped: a survey that never misreads is perfect information.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 14, 'uselessSignal''s posteriors after Heads and after Tails both stay at 0.300000 and 0.700000. What is its evii, and why?', '["12.5000, what any two-reading survey adds to that prospect, since each reading resolves some doubt.", "0.0000, because a reading equally likely under both outcomes moves nothing, so no reading changes the action.", "None, because the engine refuses a survey whose readings carry no information and returns a message in place of a value.", "Negative, because the survey returns beliefs no better than the prior while still asking the decision maker to act on them."]'::jsonb, 1, 'uselessSignal returns evWithInfo 43.0000 and evii 0.0000, sitting on the lower bound. The 12.5000 belongs to seismicBayes, a different survey on the same prospect.'),
  ('decision', 'intermediate', 'module', 'm02-imperfect-information-by-bayes', 15, 'A reader divides the EKPAN lottery survey''s EVII of 24.8250 by its EVPI of 52.0000 and calls the ratio the survey''s accuracy. Why is that wrong?', '["It is right only once the lottery survey''s cost of 8.0000 has been netted out of the numerator, since accuracy is judged on what the survey returns after its price.", "It understates accuracy, since on a two-outcome lottery EVII can never exceed half of EVPI, so the ratio must be doubled before it is read.", "It is a ratio of values that moves with the prior and the payoffs while the likelihoods stay put; accuracy lives in 0.850000 and 0.250000.", "It overstates accuracy, since the ratio counts the lottery''s bright spot reading twice, once inside evWithInfo and once inside EVPI."]'::jsonb, 2, 'The accuracy of the EKPAN lottery survey is its likelihoods; the value of that accuracy is what it changes on this decision. perfectSignal shows EVII can equal EVPI, so no half rule exists.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 1, 'A budget memo quotes 24.8250 as the worth of the EKPAN lottery survey, which is priced at 8.0000. What is wrong with the memo?', '["Nothing is wrong, since the price is sunk once the contract is signed, and a value of information is always quoted before sunk costs are taken off.", "It should quote 92.5750, the lottery''s acquisition branch, since that is what the company holds after paying for the survey.", "It understates the worth, since the survey also protects the 75.7500 the lottery is worth at the prior and that belongs in the figure.", "It quotes gross as net, overstating the survey''s contribution by exactly its price; the net value is 16.8250."]'::jsonb, 3, 'On the EKPAN lottery netEvii is evii less the cost: 24.8250 less 8.0000 is 16.8250. The 92.5750 is the whole decision with the survey bought, not the survey''s own contribution.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 2, 'Why can the EKPAN lottery survey''s price of 8.0000 be taken off before or after the readings are weighted with the same result, when a cost on one branch of a chance node cannot?', '["Because the survey price is already discounted and a chance-branch cost is not, so the engine applies the two at different points in the rollback.", "The survey price sits on the branch that buys the survey and is paid whichever reading arrives, while a chance-branch cost is paid on that branch alone.", "Because readings are signals rather than outcomes, and the engine skips any cost placed on a signal branch while weighting it.", "It cannot: taking 8.0000 off after weighting charges it 0.460000 plus 0.540000 times over, which overstates the price paid."]'::jsonb, 1, 'On the EKPAN lottery the price is paid once on every path through the survey, and 0.460000 plus 0.540000 is 1, so 100.5750 less 8.0000 is 92.5750 either way. A chance-branch cost must come off inside its branch.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 3, 'On the EKPAN lottery information tree at a survey cost of 8.0000, what is the root worth, and what does the difference between its two branches equal?', '["100.5750, since the lottery survey''s cost is paid below the reading chance node and never reaches the root of the tree.", "92.5750, and the lottery''s difference of 16.8250 is the gross EVII, since the root has already charged the survey inside its value.", "92.5750, and 92.5750 less 75.7500 is 16.8250, the net value of information.", "75.7500, since the root keeps the lottery''s prior decision and treats the survey as an option priced separately from the tree."]'::jsonb, 2, 'The EKPAN lottery information tree''s acquisition branch is 100.5750 less 8.0000 = 92.5750 against 75.7500 for no further information; the root difference 16.8250 equals netEvii.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 4, 'Reading the EKPAN lottery information tree by node values, as the Decision Tree Builder''s drawing labels them, what does a reader see under the survey branch?', '["A chance node worth 100.5750, 8.0000 more than the branch value of 92.5750, because a node''s value is taken before the cost on the branch leading into it.", "92.5750 on the lottery, since the drawing labels each node with the value of its branch after the cost has been charged.", "100.5750 on the lottery, and that figure is the survey branch''s value, because the survey cost is charged only at the root.", "8.0000 on the lottery, since the survey node is labelled with its own price and the readings carry the value."]'::jsonb, 0, 'The drawing labels a node''s own value, which excludes the cost on the branch into it. The same holds for the EKPAN lottery drill node after a bright spot, 262.7989 against a branch of 207.7989.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 5, 'Which branches under "No further information" read onOptimalPath true in the EKPAN lottery information tree at a survey cost of 8.0000?', '["Drill, since Drill is the lottery''s best action at the prior and the flag marks each decision node''s best.", "Drill and its two outcomes, since the flag marks the best path inside every decision node of the tree.", "None, because that root branch is not taken, and a branch below an untaken branch is never on the optimal path.", "All of them, since the no-information branch is the fallback the policy returns to after a poor reading on the lottery survey."]'::jsonb, 2, 'The EKPAN lottery tree marks the survey, both readings, Drill under a bright spot and Farm out under no bright spot; every branch under the untaken 75.7500 branch reads false.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 6, 'What policy does the root choice commit the company to on the EKPAN lottery when the survey is priced at 8.0000?', '["Buy the survey and drill after either reading, since the survey''s worth lies in the confidence it adds to the lottery''s prior choice of Drill.", "Drill now without the survey, since the lottery''s prior decision at 75.7500 is already positive and a survey could only confirm it.", "Buy the survey and then drill, since Drill is best at the lottery''s prior and after the reading that is more likely to arrive.", "A policy: buy the survey, drill on a bright spot and farm out without one."]'::jsonb, 3, 'On the EKPAN lottery the optimal path runs through the survey, Drill at 207.7989 after a bright spot and Farm out at 9.2361 after no bright spot. The more likely reading, at 0.540000, is no bright spot.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 7, 'At what survey price do the two root branches of the EKPAN lottery information tree tie, and why that price?', '["52.0000 on the lottery, the EVPI, since a price above the value of perfect information is the first price at which any survey loses money.", "24.8250, the gross EVII, since the acquisition branch is 100.5750 less the price and the other branch holds at 75.7500.", "100.5750 on the lottery, the price at which the acquisition branch reaches zero and stops adding anything to the root.", "16.8250 on the lottery, the net value, since the tie comes when the price has used up everything the survey adds."]'::jsonb, 1, 'On the EKPAN lottery the branches are equal when the price is 100.5750 less 75.7500 = 24.8250. EVPI is the neutral price of a survey that never misreads, and the neutral price compares two branches, never a branch with zero.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 8, 'At a survey cost of exactly 24.8250 the EKPAN lottery information tree''s root still names the acquisition. What does that name carry?', '["Only the listing order: the branches tie at 75.7500 and the engine keeps the first branch listed, so a net value of 0.0000 says nothing favours buying.", "A small positive net value hidden by printing to four decimals, since the engine compares the unrounded lottery branch values.", "A preference for information whenever the two lottery branches fall within the engine''s tolerance of 1e-6 of each other.", "A real recommendation, since at the neutral price the survey still lowers the chance of drilling a dry hole on the lottery."]'::jsonb, 0, 'At a cost equal to the EKPAN lottery''s EVII the two root branches tie and the strictly-greater comparison keeps the acquisition, listed first. Nothing in the engine flags the tie, so read netEvii beside every root choice.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 9, 'costExactlyNetZero returns root branch values 43.0000 and 43.0000 and bestBranchIndex 0. What would listing the no-information branch first change?', '["The recommendation, which becomes doing without the survey, while the root value stays 43.0000.", "Nothing, since the engine breaks exact ties toward the branch with fewer nodes below it, which is the no-information branch in either order.", "The root value, since the rollback weights a decision node''s branches in listing order before it takes the maximum.", "The tie price, which moves away from the survey''s gross value of 12.5000 toward the prior."]'::jsonb, 0, 'A decision node replaces the incumbent only on a strictly greater value, so the first listed wins a tie. The survey there costs 12.5000, its gross value, and the root is 43.0000 whichever branch is named.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 10, 'At a survey cost of 28.0000 the EKPAN lottery acquisition branch is still worth 72.5750. A reader buys the survey because that branch is comfortably positive. What does the tree say?', '["Buy, since a positive acquisition branch on the lottery means the survey returns more than its price and so adds value to the decision.", "Buy, since 28.0000 is still under the lottery''s EVPI ceiling of 52.0000.", "Do not buy: the no-information branch at 75.7500 is worth more, and the net value is -3.1750.", "Do not buy, as the branch is below the lottery survey''s gross worth of 100.5750."]'::jsonb, 2, 'On the EKPAN lottery a positive acquisition branch ignores the other root branch: 72.5750 against 75.7500 gives -3.1750. The 100.5750 is evWithInfo, and the gross value is 24.8250.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 11, 'Across the EKPAN lottery cost sweep from 0.0000 to 32.0000, which of these moves?', '["The success posterior after a bright spot, which falls from 0.646739 as a dearer survey is bought on the same lottery.", "The gross EVII, which shrinks from 24.8250 at no cost down to -7.1750 at the top of the lottery sweep.", "The no-information branch, which rises above 75.7500 as the lottery survey becomes less attractive to buy.", "The acquisition branch and the net value, one for one with the price."]'::jsonb, 3, 'The price is paid before any reading on the EKPAN lottery, so pSignal 0.460000, the posteriors, the actions and the gross 24.8250 stay fixed; only the acquisition branch and netEvii fall, to 68.5750 and -7.1750 at 32.0000.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 12, 'Why does the EKPAN lottery information tree''s root never fall below 75.7500, however dear the survey?', '["The engine floors the root at the lottery''s prior EMV as a clamp.", "Declining the survey is always available, and the root takes the larger of its two branches.", "75.7500 is the least the lottery''s Drill action can return after a bright spot, which the survey guarantees.", "The engine caps any survey price at its EVII, so the lottery''s acquisition branch cannot fall further than 75.7500."]'::jsonb, 1, 'Nothing is clamped or capped: at 32.0000 the EKPAN lottery acquisition branch really is 68.5750, and the root is 75.7500 because the no-information branch wins the maximum.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 13, 'seismicCost20 returns a root emv of 43.0000 with bestBranchIndex 1 and root branch values 35.5000 and 43.0000. What happened?', '["The engine refused the survey because its price passed the prospect''s EVPI of 35.0000, and fell back to the prior decision in place of a value.", "The survey changed the prior decision, and 43.0000 is the value of acting on the negative seismic reading that the survey returns most often.", "Index 1 is the survey branch, and 35.5000 is what the tree charged for the survey out of its 43.0000 root.", "The survey price of 20.0000 exceeds its gross value of 12.5000, so the root takes the no-information branch."]'::jsonb, 3, 'The seismic survey''s evWithInfo is 55.5000, so its acquisition branch is 55.5000 less 20.0000 = 35.5000 against 43.0000. The price is below the prospect''s EVPI of 35.0000 and nothing is refused.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 14, 'The published noSignals case asks for an information tree with no readings at all and a survey cost of 0.0000. What does the engine return?', '["A refusal: an information tree needs a reading to build its chance node.", "A survey branch worth 43.0000 tied with no information, and the first branch listed, the acquisition, named as the choice.", "The plain prospect decision, a root \"Choose action\" at 43.0000 with no survey branch.", "A survey branch worth the EVPI, as a survey with no readings cannot misread."]'::jsonb, 2, 'noSignals returns root "Choose action" at 43.0000 with branch values 43.0000, 18.0000 and 0.0000: the three actions of the prospect and nothing to buy.'),
  ('decision', 'intermediate', 'module', 'm03-buying-the-information', 15, 'A manager asks the EKPAN lottery cost sweep whether a cheaper survey with weaker likelihoods would be worth more net. What can the sweep answer?', '["Yes, by reading the lottery''s net value at the cheaper price, since price is the only way a survey''s quality reaches the information tree.", "Nothing, since the sweep holds the survey''s likelihoods fixed and every survey quality needs its own tree.", "Yes, since the lottery''s net value falls one for one with price, so any cheaper survey is worth more net whatever its likelihoods are.", "Only that any survey adds value below the lottery''s 24.8250, where the sweep stops paying."]'::jsonb, 1, 'The EKPAN lottery sweep values one survey at many prices; its gross 24.8250 comes from 0.850000 and 0.250000. A weaker survey has a different gross value, and the engine has no budget constraint either.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 1, 'A symmetric survey of accuracy 0.800000 runs on the EKPAN lottery, where success has a prior of 0.350000. How often does it read success?', '["0.800000, because a survey of that accuracy says success on that share of the wells it looks at.", "0.350000, since a reading can only turn up as often as the outcome it reports, whatever the accuracy.", "0.410000, from successes read correctly plus dry holes misread: 0.350000 x 0.800000 + 0.650000 x 0.200000.", "0.682927, the chance of success once the survey has read success, which is the same event seen from the reading."]'::jsonb, 2, 'Dry holes are common, so the 0.200000 of them that misread push the success reading above success itself, 0.410000 against 0.350000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 2, 'On the EKPAN lottery a symmetric survey of accuracy 0.800000 reads success. What is the chance the well succeeds?', '["0.682927, the joint 0.350000 x 0.800000 divided by the chance of the reading, 0.410000.", "0.800000, because the survey is right that often and it has just said success.", "0.410000, the chance of a success reading, which is what the survey reports.", "0.118644, since a survey that reads success over a common dry hole is usually misreading."]'::jsonb, 0, 'Reading accuracy as a posterior drops the prior; the prior of 0.350000 still weighs in, which is why the posterior sits below the accuracy. 0.118644 is the posterior after a dry reading.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 3, 'At accuracy 0.600000 a dry reading on the EKPAN lottery moves the success probability from 0.350000 to 0.264151, and the table''s evii is 0.0000. Why is a real change of belief worth nothing?', '["The survey is still a coin at that accuracy, so neither reading tells the engine anything about the rock and both posteriors stay exactly where the prior put them.", "The survey has a small positive gross value that falls short of the survey cost of 8.0000, and the table prints any value that does not pay for itself as a net zero.", "The engine computes a negative value for a survey that changes nothing and clamps it at zero, because information cannot be reported as a loss.", "Both readings still lead to Drill, since 0.264151 stays above the switch at 0.228571, so the weighted value with information is Drill at the prior, 75.7500."]'::jsonb, 3, 'Drill is a straight line in p and the posteriors weighted by their reading chances return the prior, so the value with information equals the emvPrior of 75.7500. A coin is accuracy 0.500000, where both posteriors are 0.350000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 4, 'At accuracy 0.550000 the engine returns an evii of -1.42e-14 on the EKPAN lottery. What is that number?', '["A genuine small loss, because at that accuracy a misleading reading occasionally sends the company to the wrong action and costs it money on average.", "Floating-point residue from subtracting two equal sums, which the table prints as 0.0000.", "A negative value that escaped the clamp meant to hold information at zero, so the engine is reporting a defect in its own floor.", "A flag meaning the likelihood columns failed the 1e-6 tolerance, returned in place of a refusal message."]'::jsonb, 1, 'Both readings lead to Drill, so the value with information and the emvPrior are the same 75.7500 computed two ways. Information derived by Bayes is never worth less than 0; the table prints residue below 1e-9 as 0.0000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 5, 'A symmetric survey on the EKPAN lottery first changes an action at accuracy 0.645051. How does its value behave as accuracy passes that point?', '["It jumps straight to 0.7250, the farm-out value the survey gains the moment a dry reading switches the action.", "It starts from zero with no jump, because at the flip Drill and Farm out are equal at the dry reading''s posterior, and it reads 0.7250 at 0.650000.", "It began rising at 0.500000, where the posteriors first move away from the prior, and 0.645051 is only where the rise becomes visible at four decimals.", "It starts at 0.650000, where a success reading gives a posterior of 0.500000 and the survey becomes worth buying."]'::jsonb, 1, 'Switching gains nothing at the exact flip and the gain grows as the dry posterior falls further, 0.7250 at 0.650000 and 8.0500 at 0.700000. Below 0.645051 the value is exactly 0.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 6, 'Why can a success reading from a symmetric survey on the EKPAN lottery never change the action?', '["It arrives less often than a dry reading, so its weight in the value with information is too small to move the choice.", "The Farm out line, 95 p, rises faster than Drill above the prior, so a higher success probability favours the farm-out anyway.", "A symmetric survey reads success and dry with the same accuracy, so only the reading with the lower prior can carry information.", "It only pushes success above the prior of 0.350000, which already chooses Drill."]'::jsonb, 3, 'Drill is 445 p - 80 and Farm out 95 p, crossing at 0.228571. Only a dry reading can change the action, once it pushes success under that switch.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 7, 'The EKPAN lottery''s survey costs 8.0000. Across the symmetric rows at accuracies 0.650000 and 0.700000, which pays for itself?', '["Only 0.700000: 0.650000 changes a choice and is worth 0.7250 gross, far short of the cost, while 8.0500 at 0.700000 just clears it.", "Both, because each one changes the action after a dry reading, and a survey that changes a choice has already shown it is worth buying at any price.", "Neither, since the value has to reach the EVPI of 52.0000 before a survey is worth its cost.", "Only 0.650000, because the value of a survey is largest where it first changes the decision and falls away as accuracy rises beyond it."]'::jsonb, 0, 'Changing a choice makes the gross value positive; it does not make it larger than the price. The margin at 0.700000 is thin, 8.0500 against 8.0000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 8, 'From accuracy 0.650000 upward the symmetric survey on the EKPAN lottery is worth 0.7250, 8.0500, 15.3750 and so on, rising by the same step each 0.050000. Why equal steps?', '["The posteriors rise in equal steps with accuracy, so the Drill value after a success reading grows by the same amount each row.", "The evii is a fixed fraction of the EVPI of 52.0000, and that fraction grows in proportion to accuracy.", "The actions are fixed across those rows, Drill after a success reading and Farm out after a dry one, so the value is four joint terms each a straight line in accuracy.", "The engine interpolates between the switch accuracy and a perfect reading instead of running Bayes on each row."]'::jsonb, 2, 'The terms are 0.350000 x a x 365.0000, 0.650000 x (1 less a) x -80.0000 and 0.350000 x (1 less a) x 95.0000. The posteriors are not linear: 0.556818, 0.617647, 0.682927.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 9, 'Accuracy 0.750000 is halfway from a coin to a perfect survey. On the EKPAN lottery, what is it worth?', '["Half the EVPI of 52.0000, because value is proportional to accuracy between a coin, worth nothing, and a perfect survey, worth the EVPI.", "30.0250, since the value line runs straight from the coin at 0.500000 up to the EVPI at 1.000000 and passes through the midpoint above half.", "22.7000, since the symmetric survey is worth the same share of the EVPI as its success reading''s posterior.", "15.3750, well under half the EVPI, because the stretch up to 0.645051 buys nothing."]'::jsonb, 3, 'The line is straight only from the flip at 0.645051; before that the value is 0.0000. 30.0250 and 22.7000 belong to accuracies 0.850000 and 0.800000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 10, 'A survey on the EKPAN lottery is sold as perfect, but its success reading arrives with chance 0.410000. What does that chance show?', '["It cannot be perfect: a perfect reading arrives exactly as often as success, 0.350000, so some of these readings are wrong.", "It is perfect only if its success posterior reaches 1.000000, which the reading chance alone can neither confirm nor rule out on any lottery.", "Nothing about perfection, because a perfect survey reads success with chance 0.500000 so that it stays unbiased across both outcomes.", "It is perfect, since a reading that arrives more often than success simply catches every success and some extra."]'::jsonb, 0, 'At accuracy 1.000000 the success reading''s chance is 0.350000, the prior, and the posteriors are 1.000000 and 0.000000; 0.410000 is accuracy 0.800000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 11, 'On the EKPAN lottery, how do a symmetric survey at accuracy 0.500000 and one at 0.600000 differ, given that both are worth 0.0000?', '["They do not differ, because a survey worth 0.0000 cannot move belief and both leave the success probability at the prior of 0.350000.", "The first is worthless because it is cheap and the second useless because it is expensive, since value is judged after the cost of 8.0000.", "The first is useless, leaving both posteriors at 0.350000; the second moves success to 0.446809 or 0.264151 and is worthless only because Drill follows both readings.", "The second is worth a small amount hidden by rounding, because any movement of the posteriors adds value that the four decimal print suppresses."]'::jsonb, 2, 'A useless signal cannot move belief; a worthless one moves belief and changes nothing. At 0.600000 the dry posterior stays above the switch 0.228571.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 12, 'The published dominantAction lottery has emvPrior 65.0000 and evWithPerfect 65.0000. What can the most accurate survey be worth on it?', '["Up to 65.0000, the emvPrior, which caps any value the survey can add to the decision.", "0.0000, because its evpi is 0.0000 and no survey can be worth more than perfect information.", "0.0000 at low accuracy, then something once a reading is accurate enough to change which action is chosen.", "65.0000 for a perfect survey, since knowing the outcome first is worth evWithPerfect on any lottery."]'::jsonb, 1, 'One action is best whatever happens, so evpi is 65.0000 less 65.0000 = 0.0000, and 0 <= evii <= evpi forces every signal to 0.0000.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 13, 'An analyst types a survey on the EKPAN lottery whose likelihoods over Success are 0.850000 and 0.050000. What does the engine do?', '["It refuses, with a message naming the column and its sum: \"Likelihoods P(signal | \"Success\") sum to 0.900000, expected 1\".", "It rescales the column to sum to 1 and values the survey as if the analyst had typed it correctly, without saying that it has done so.", "It treats 0.850000 as the accuracy of a symmetric survey and ignores the second entry.", "It values the survey anyway and reports an evii above the EVPI of 52.0000 as a warning sign."]'::jsonb, 0, 'The engine takes likelihood columns and insists each outcome''s column sums to 1; accuracy is only shorthand for one pair of them. It never repairs a column.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 14, 'The published accuracySweep_0p7 case returns an evii of 6.5000, while the EKPAN lottery''s symmetric survey at the same accuracy 0.700000 is worth 8.0500. Why do they differ?', '["One of them has had the EKPAN lottery''s survey cost of 8.0000 taken off, which accounts for the gap between two otherwise identical runs.", "The published case uses an asymmetric survey at that accuracy, so it is right about dry holes less often than about successes.", "The golden was written at a coarser rounding than the engine returns, so the two agree before rounding and differ after.", "They run different lotteries: the drillFarmOut prospect at a prior of 0.300000, with an EVPI of 35.0000."]'::jsonb, 3, 'Mixing a published case''s inputs with the EKPAN lottery is the mistake. Both lotteries have the same shape, nothing at a coin and the EVPI at a perfect reading: 35.0000 on the prospect, 52.0000 on the EKPAN lottery.'),
  ('decision', 'intermediate', 'module', 'm04-accuracy-and-value', 15, 'The CSEM survey on the EKPAN lottery shows a bright spot over 0.850000 of successes and 0.250000 of dry holes. A reader books it as a symmetric survey of accuracy 0.850000, worth 30.0250. What is wrong?', '["Nothing, because accuracy is the chance of a correct bright spot over a success, and that is 0.850000.", "It should be booked at its weaker side, accuracy 0.750000, worth 15.3750, since a survey is only as good as its worst reading.", "It is not symmetric: it is right about a dry hole only 0.750000 of the time, and it is worth 24.8250, between the symmetric rows at 0.800000 and 0.850000.", "It should be booked at the average of its two sides, accuracy 0.800000, worth 22.7000, because symmetry is a mean of both columns."]'::jsonb, 2, 'Only the engine''s Bayes run on the two actual columns values it: 24.8250, above 22.7000 and below 30.0250.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 1, 'An analyst types the EKPAN lottery into the VOI Analyzer with a success payoff of 365.0000 and a drill cost of 55.0000. What catches the mistake?', '["The consistency check, which withholds the value of information when a payoff and the decision cost overlap.", "Only a hand rollback at the stated chances: the EMV without information no longer matches 75.7500, and the Analyzer has no way to know the drill was charged twice.", "A refusal naming the payoff, since the Analyzer does not accept a payoff that is already net of its decision cost.", "The EVPI card, which the Analyzer flags whenever it exceeds the EMV without information by more than the survey cost."]'::jsonb, 1, 'A payoff is the money before the decision cost; typed at 365.0000 with the cost of 55.0000 it charges the drill twice, silently. The check is the EMV without information against 75.7500.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 2, 'Which actions does the VOI Analyzer weigh when it values a survey?', '["The named decision, \"Do Not\", and one optional alternative such as a farm-out typed with its own payoffs.", "One action for each outcome typed, so a study with Success and Dry hole gets two actions and a third outcome adds a third.", "As many actions as indicators, each the best response to one indicator, chosen by the Analyzer from the posteriors typed.", "The named decision at its cost, and \"Do Not\" with every payoff 0."]'::jsonb, 3, 'The Analyzer offers exactly two actions and no third branch; a farm-out or partner option has to be squeezed into act or do not.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 3, 'An analyst enters No bright spot at 64 percent beside Bright spot at 46.000000 percent for the EKPAN lottery''s survey. What comes back from the repaired VOI Analyzer?', '["A refusal before any card: \"Indicator chances sum to 110 percent, expected 100\".", "The two cards that use only the stated chances, 75.75 and 52.00, with the other values and the diagram withheld.", "Full cards computed after rescaling the two indicator chances so that they sum to 100 percent.", "A refusal that names the Bright spot box as the one to correct."]'::jsonb, 0, 'Percents that are not a distribution are refused outright, and the message names the sum in percent. Withholding is the answer to chances that sum correctly but contradict the stated outcome chances.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 4, 'Suppose the CSEM survey''s indicator chances for the EKPAN lottery are entered as 56 and 44 percent while both posteriors keep their Bayes values. Which results does the repaired check let through?', '["A refusal, because the indicator chances no longer agree with the stated outcome chances and the Analyzer declines to compute any card.", "A gross value of information of 40.62 beside an EVPI of 52.00, which is what these inputs produce on the four cards and in the sentence.", "EMV without information 75.75 and EVPI 52.00, withholding EMV with information, the gross and net value and the diagram.", "The gross value of 19.84, after rescaling the posteriors so that they fit the stated success chance of 0.350000 again."]'::jsonb, 2, 'The chances sum to 100, so nothing is refused, but they imply success 0.404952 against the stated 0.350000, more than 0.005 away. 40.62 is what the Analyzer printed before the repair; the check never repairs.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 5, 'Before the repair, the VOI Analyzer printed a gross value of information of 69.00 beside an EVPI of 63.00 for a Positive Seismic posterior row summing to 130 percent. What happens now, and what was wrong with 69.00?', '["The inputs are refused with \"Outcome chances given \"Positive Seismic\" sum to 130 percent, expected 100\"; 69.00 was a survey worth more than knowing the answer.", "The value is withheld while 15.00 and 63.00 stay on their cards, since a row that sums past 100 contradicts the stated chances.", "The value is capped at 63.00, because EVPI is the ceiling and a survey can reach it but never pass it.", "The row is rescaled to 100 percent and valued, and 69.00 was wrong only because the old build skipped that step."]'::jsonb, 0, 'A row summing to 130 percent is not a set of chances at all, so it is refused; a withholding is for chances that cannot all be true together. No survey beats perfect information at 63.00.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 6, 'In the Analyzer''s default study, Positive Seismic comes up 40 percent of the time with Success Case at 60 percent, and Negative Seismic 60 percent with Success Case at 10 percent. What check do these typed numbers have to pass?', '["The Success Case entries down the column must add to 100 percent, the way a distribution over indicators would.", "Weighted by the indicator chances they must return the stated Success Case: 40 percent x 60 percent + 60 percent x 10 percent = 30 percent.", "Each posterior must be at least the stated 30 percent, because a survey can only raise the chance it reports on.", "The indicator chances must match the outcome chances, 40 percent against 30 percent and 60 percent against 70 percent, within 0.005 in decimals."]'::jsonb, 1, 'Posteriors carry the prior inside them, so their weighted average must give back the stated chance; the repaired Analyzer withholds when an implied chance sits more than 0.005 from it.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 7, 'The EKPAN lottery is typed into the VOI Analyzer with its Bayes posteriors at full precision and a survey cost of 8.0000. After No bright spot, Drill is worth -36.7361. What does the EMV with Information card read?', '["100.5750, because after No bright spot the Analyzer takes the best remaining action, the farm-out at 9.2361, weighted by 0.540000.", "95.5875, because the card titled EMV with Information is the value before the survey cost, the same quantity as the tree engine''s evWithInfo.", "No value: the card is withheld because Drill is negative after one indicator.", "87.59, from 0.460000 x 207.7989 + 0.540000 x 0.0000 = 95.5875 less the survey cost."]'::jsonb, 3, 'The Analyzer can only choose "Do Not" at 0 after No bright spot, and the card is after the survey cost; the root of the drawn tree is 87.5875.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 8, 'From the EKPAN lottery''s Analyzer entries, Bright spot 46.000000 percent and P(Success | Bright spot) 64.673913 percent, which line recovers the likelihood of a bright spot over a dry hole?', '["0.353261 x 0.650000 / 0.460000, dividing by the chance of the indicator as Bayes does for a posterior.", "0.353261 read directly, since the dry-hole share left in the Bright spot row is how often dry holes show one.", "0.353261 x 0.460000 / 0.650000, giving the survey''s own 0.250000.", "0.646739 x 0.460000 / 0.350000, since the bright spot''s likelihood is the same over either outcome."]'::jsonb, 2, 'P(indicator | outcome) = P(outcome | indicator) x P(indicator) / P(outcome); the indicator chance belongs on top. The last line recovers 0.850000, the likelihood over a success.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 9, 'A reviewer checks the EKPAN lottery typed into the VOI Analyzer: the cards read 75.75 without information and 52.00 for EVPI, matching the lottery''s 75.7500 and 52.0000. Has the typing captured the decision?', '["Yes, because the emvPrior and the EVPI together pin down every action on the lottery, and a missing action would move at least one of them.", "No: those two numbers cannot see the missing farm-out, which only the value with information exposes.", "Yes, provided the inputs are consistent, since a consistent study with matching cards can only differ from the lottery in rounding.", "Yes, since a missing action would have been refused."]'::jsonb, 1, 'Drill beats Farm out at the prior, 75.7500 against 33.2500, and under perfect information a known dry hole pays 0.0000 either way, so both rows match. After No bright spot the farm-out''s 9.2361 is lost.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 10, 'The Analyzer''s engine returns a gross voi of 33.00 on its default study. Where does a user see it?', '["Only in the Decision Guidance sentence and the CSV export.", "On the card titled EMV with Information, which on the default study reads the gross value of the survey.", "On the card titled Net Value of Info (Net VOI).", "On the EVPI card, beside the value of perfect information, so the two gross ceilings can be read together."]'::jsonb, 0, 'The panel shows four cards: EMV without Information 15.00, EMV with Information 38.00, Net VOI 23.00 and EVPI 63.00. The fifth number is only in the sentence and the CSV.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 11, 'On the Analyzer''s default study with the survey at 10.0000, the cards read 15.00 without information and 38.00 with information. What is the net value of information?', '["13.00, since the survey cost still has to come off the EMV with Information card before it is set against 15.00.", "33.00, because the difference between the two EMV cards is the gross value and the net comes from the separate cost box.", "28.00, the EMV with Information card less the survey cost, since that difference is what the survey adds after it is paid for.", "23.00, because 38.00 is already after the survey cost."]'::jsonb, 3, 'The card reads 48.00 at a cost of 0 and 38.00 at 10.0000, so it is net of the cost. Subtracting 10.0000 again charges the survey twice; 13.00 is the card at a cost of 20.0000.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 12, 'A report on the Analyzer''s default study sets the Net VOI card, 23.00, beside the EVPI card, 63.00, and concludes the survey captures about a third of what perfect information would. What is wrong?', '["Nothing, because both cards are after the survey cost of 10.0000, so the ratio compares like with like.", "The EVPI card is itself net of the survey cost, so the fair comparison takes the cost off 63.00 before setting it beside 23.00.", "The comparison should use EMV with Information, 38.00, against 63.00, since that card holds the survey''s value.", "It sets a value after cost against a ceiling before cost; the fair pair is the gross 33.00 against 63.00, and 33.00 is on no card."]'::jsonb, 3, 'EVPI charges nothing for the information. The gross value, 23.00 plus the cost of 10.0000, is 33.00, which appears only in the guidance sentence and CSV.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 13, 'At a survey cost of 33.0000 on the Analyzer''s default study the Net VOI card reads 0.00. What do the verdict and the drawn tree''s root say?', '["The verdict calls acquiring positive and the root acquires, since a net value of zero counts as no loss and so as a gain.", "The verdict says the information is not justified and the root reads \"No further information\", because acquiring is chosen only when it strictly gains over not acquiring.", "The verdict says the information exactly pays for itself, and the root still reads \"Acquire 3D Seismic Survey\" because the tied branches keep the first listed.", "The verdict says it exactly pays for itself and the root reads \"No further information\", the branch kept when two values are equal."]'::jsonb, 2, 'The two root branches tie and the engine replaces a branch only on a strictly greater value. At 40.0000 the card reads -7.00 and the root turns to "No further information".'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 14, 'On the EKPAN lottery the tree engine returns an evWithInfo of 100.5750, while the Analyzer''s EMV with Information card reads 87.59 at a survey cost of 8.0000. What separates them?', '["The card is after the survey cost and the Analyzer has dropped the farm-out: adding 8.0000 back gives 95.5875, still short of 100.5750.", "Only the survey cost, since the card subtracts 8.0000 and the tree engine does not, and the rest of the gap is two-decimal rounding of the card.", "The Analyzer rounds the posteriors to whole percents before valuing, which moves the value after each indicator.", "The Analyzer subtracts the survey cost after each indicator as well as once at the root, charging it twice."]'::jsonb, 0, '0.460000 x 207.7989 + 0.540000 x 9.2361 = 100.5750 with the farm-out; without it the No bright spot branch pays 0.0000, giving 95.5875.'),
  ('decision', 'intermediate', 'module', 'm05-the-voi-analyzer', 15, 'The EKPAN lottery''s survey is quoted at 20.0000. What do the three-action information tree and the two-action VOI Analyzer conclude?', '["Both acquire, since the matching 75.75 and 52.00 show the Analyzer typed the same decision the tree rolls back.", "The tree acquires with a net value of 4.8250; the Analyzer''s gross value, 19.8375, is under the cost, so its net is negative and its verdict says not justified.", "Both decline, because 20.0000 exceeds the Analyzer''s gross value and the tree reads the same survey through the same posteriors.", "The Analyzer acquires with a net value of 4.8250 and the tree declines, because the tree charges the survey on its root branch."]'::jsonb, 1, 'With the farm-out the survey is worth 24.8250 gross; without it 19.8375. The gap is the dropped action''s 9.2361 weighted by the 0.540000 chance of No bright spot, and it decides this price.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Working the EKPAN lottery at its stated prior of 0.350000, an analyst''s Bayes arithmetic gives a survey value of 61.7143. What should they conclude before checking a single line?', '["It is plausible, because a good survey can be worth more than perfect information when the prior sits near the switch.", "It is right, since the EVPI peaks at 61.7143 and a survey that reads the rock well reaches that peak.", "It is the gross value, and taking the survey cost of 8.0000 off it brings the net value under the EVPI.", "It is wrong: it exceeds the EVPI of 52.0000 written down at step two, and 61.7143 is the EVPI at the switch 0.228571."]'::jsonb, 3, 'The ceiling comes before Bayes so that any value above it, or below 0, is caught without a second calculation. 0 <= evii <= evpi holds for every derived survey.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Which line is the EKPAN lottery''s value with the CSEM survey, before its cost?', '["0.350000 x 207.7989 + 0.650000 x 9.2361, weighting each signal''s value by the prior of the outcome it points to", "0.460000 x 207.7989 + 0.540000 x 9.2361 = 100.5750", "0.460000 x 207.7989 + 0.540000 x -36.7361, keeping Drill after No bright spot because Drill is best at the prior", "0.460000 x 207.7989 + 0.540000 x 9.2361 less 8.0000, taking the survey cost out before the value is called gross"]'::jsonb, 1, 'Weight by pSignal, never by the prior, and take the best action after each signal: Farm out at 9.2361 after No bright spot. EVII is 100.5750 less 75.7500 = 24.8250.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'An analyst reads the CSEM survey''s 0.850000 as the chance of success after a bright spot on the EKPAN lottery. What does that do?', '["Nothing to the value, since a likelihood and a posterior agree whenever the survey is more likely to be right than wrong about the rock.", "It lowers Drill after a bright spot, because 0.850000 ignores how often dry holes show one too and so understates the chance of success.", "It values Drill after a bright spot at 298.2500 against the posterior''s 207.7989, because a likelihood is read as a posterior.", "It changes only the chance of a bright spot, 0.460000, and leaves the Drill value after one where Bayes put it."]'::jsonb, 2, 'The posterior is 0.646739 because the 0.250000 of dry holes that show a bright spot still count; reading 0.850000 overvalues the drill.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The CSEM survey on the EKPAN lottery is quoted at exactly 24.8250. What does the information tree recommend, and what does that mean?', '["\"Acquire CSEM survey\", only because the two root branches tie at 75.7500 and the engine keeps the branch listed first; the money is the same either way.", "\"No further information\", because a net value of zero buys nothing and the engine prefers not to spend on information.", "\"Acquire CSEM survey\", but by floating-point residue, since the two branch values differ in their last binary digits.", "\"Acquire CSEM survey\" on merit, because 24.8250 is below the gross value and the net value at that price is 16.8250."]'::jsonb, 0, 'The neutral price is the gross evii, 24.8250, where acquire is 100.5750 less 24.8250 = 75.7500. An exact tie goes to the first branch; float residue is what decides the drill against farm-out choice at 0.228571.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The VOI Analyzer values the CSEM survey on the EKPAN lottery at a gross 19.84, while the tier''s own Bayes run gives 24.8250. Why?', '["The Analyzer rounds the typed posteriors, and the value of information is sensitive enough that rounding alone takes it from 24.8250 to 19.84.", "The Analyzer''s figure is after the survey cost of 8.0000 and the tree''s is before it, and the rest of the gap is two-decimal rounding.", "The Analyzer offers two actions, so after No bright spot it can only walk away, losing the farm-out''s 9.2361 on the 0.540000 of readings that would use it.", "The Analyzer uses a smaller EVPI for the two-outcome lottery, and its value of information is scaled down to stay under it."]'::jsonb, 2, 'With the full posteriors typed, emvPrior and EVPI still match at 75.75 and 52.00; only the value with information moves, from 100.5750 to 95.5875.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A report on the EKPAN lottery in the VOI Analyzer writes "net VOI 11.84 of a possible 52.00". What is wrong with the pairing?', '["Nothing, since both numbers come from the Analyzer''s cards on the same inputs and the same survey cost of 8.0000.", "The EVPI card should be reduced by the survey cost first, because the ceiling on a survey cannot include the price of it.", "The pairing should use 24.8250 against 52.0000, because the Analyzer''s own cards on the EKPAN lottery cannot be compared at all.", "It sets a net value beside a gross ceiling; the fair pair is the gross 19.84 against 52.00, and 19.84 is on no card."]'::jsonb, 3, 'EVPI charges nothing for information, so it pairs with the gross value, 11.84 plus the cost of 8.0000. On the Analyzer the gross value appears only in the guidance sentence and the CSV.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Which single number does the EKPAN lottery''s work on perfect information, on actions after each signal and on accuracy all lean on?', '["The EVPI, 52.0000, which every survey value and every action choice after a signal is measured against.", "The drill against farm-out switch, 80 / 350 = 0.228571.", "The prior, 0.350000, since every posterior is compared with it to decide whether the reading changes the action.", "The chance of a bright spot, 0.460000, which sets the weight on the drill branch in every step of the work."]'::jsonb, 1, 'EVPI peaks there at 61.7143, each posterior''s action depends on its side of it, and a symmetric survey is worth 0.0000 until a dry reading carries success under it, first at accuracy 0.645051.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A close-out note on the EKPAN lottery lists Drill at 75.7500, an EVPI of 52.0000, a CSEM survey worth 24.8250 gross, and a chance of 0.500000 that Drill loses money. Which entry does not belong to the lottery?', '["The loss chance: on the lottery Drill loses 80.0000 with probability 0.650000, and 0.500000 belongs to the three-outcome EKPAN tree, whose drill branch is 105.0000.", "The EVPI: 52.0000 is the EKPAN tree''s figure, and the lottery''s own EVPI is 61.7143 at its switch.", "The survey value: 24.8250 is the tree''s figure, and the lottery''s is the two-action 19.84.", "The drill value: 75.7500 is the lottery''s value after the CSEM survey cost has been taken off, and the lottery''s Drill before any survey is bought is worth 105.0000."]'::jsonb, 0, 'The EKPAN lottery has two outcomes and no later decision: emvPrior 75.7500, evpi 52.0000, evii 24.8250, and Drill loses on the dry hole 0.650000 of the time. The EKPAN tree adds a Marginal find with a later decision; its drill branch of 105.0000 loses money with probability 0.500000. Name the model beside every EKPAN number.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'On IRRI, both indicators are typed 20 / 80 percent into the Analyzer defaults. What does the repaired Analyzer report?', '["EMV without information 15.00 and EVPI 63.00, withholding the rest, because the typing implies success 0.200000 against the 0.300000 stated.", "A gross value of information of -15.00 and a net value of -25.00 on its cards, showing that a survey read this way is worse than useless to the decision.", "A refusal, because two identical rows of chances are not a distribution and cannot be valued.", "A gross value of 0.00, since two identical indicators move nothing and so leave the value at zero."]'::jsonb, 0, 'The rows sum to 100 so nothing is refused, but the implied chance sits far more than 0.005 from the stated one. The -15.00 was printed before the repair, and information derived by Bayes is never worth less than 0.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'The EKPAN lottery''s Drill action is chosen at 75.7500 against Farm out at 33.2500, although it loses 80.0000 with probability 0.650000. A manager wants the survey credited for sparing a dry hole. What does the tier''s engine say?', '["It credits the survey with the 80.0000 loss avoided on each dry reading, weighted by how often dry readings arrive.", "It adds a risk premium to the farm-out after a dry reading, which is why the survey is worth 24.8250 on this lottery.", "Nothing beyond the mean: the engine is risk neutral, so avoiding a loss counts only at its expectation, and a dry hole spared on a well drilled anyway adds no value.", "It discounts the dry hole''s loss more heavily than the success, which is how the survey''s value reflects the downside."]'::jsonb, 2, 'Every number in the tier is risk neutral and undiscounted: the rollback maximises the mean, so comfort is not money.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Working the EKPAN lottery by hand, an analyst''s posteriors weighted by their signal chances do not return the prior of 0.350000. What does that show?', '["A survey informative enough to move the average belief away from the prior, which is what gives it a value above zero.", "A posterior divided by the wrong thing, so every value built on it is wrong before any action is chosen.", "Inputs that contradict each other, which the tree engine would withhold in the way the Analyzer does.", "Rounding to six decimals, which the engine allows for within its 1e-6 tolerance on each probability column it checks."]'::jsonb, 1, 'The check is 0.460000 x 0.646739 + 0.540000 x 0.097222 = 0.350000; a survey moves belief up on one reading and down on the other, never on average.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'An analyst takes the EKPAN lottery''s survey cost of 8.0000 off inside each signal branch and again at the information tree''s root. What net value do they report?', '["16.8250, since a constant taken off every signal branch cannot change which action wins after either signal, and so cannot change the money either.", "12.8250, since the inner charge is weighted by the signal chances and only about half of it survives to reach the root.", "0.8250, because charging the survey on every branch of the tree is the same as quoting it at 24.0000.", "8.8250, where the net value is 16.8250, because the weights sum to 1 and the inner charges add one more 8.0000."]'::jsonb, 3, 'The acquire branch becomes 84.5750 instead of 92.5750 against 75.7500. The actions do not change, but the money does: subtract the cost once, after the Bayes value.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Why can the tree engine never withhold a value of information the way the VOI Analyzer does?', '["It quietly rescales any posteriors that fail the check so that they return the stated prior before it values the survey on its own.", "It has a wider consistency tolerance than the Analyzer, so inputs that fail 0.005 there pass here.", "It takes likelihoods and derives the posteriors itself, so its inputs cannot contradict the stated outcome chances.", "It does withhold, but its withheld values print as 0.0000 in the table rather than as a missing card."]'::jsonb, 2, 'Contradictory inputs are only reachable when posteriors are typed by hand, which the Analyzer allows and the tree engine does not.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On the EKPAN lottery, EVPI is 52.0000 at the stated prior and 0.0000 on the dominantAction lottery. Where on the EKPAN lottery''s prior sweep is it largest, and why there?', '["At the switch 0.228571, 61.7143, because the prior decision is least settled there.", "At the stated prior 0.350000, 52.0000, because that is where the survey is actually bought.", "At a prior of 0.500000, where success and a dry hole are equally likely and uncertainty is greatest.", "At a prior near 0.900000, where the Drill payoff dominates and knowing the rare dry hole saves most."]'::jsonb, 0, 'The sweep reads 54.0000 at 0.200000, 61.7143 at 0.228571 and 60.0000 at 0.250000; at 0.500000 it is 40.0000. The value of knowing peaks where the choice turns.'),
  ('decision', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'The EKPAN lottery''s symmetric survey at accuracy 1.000000 and the Bayes run on the published perfectSignal case both reproduce perfect information. What ties them to it?', '["Each reading arrives with chance 0.500000, so the survey splits the wells evenly and the value doubles to reach the EVPI.", "Each reading occurs under one outcome only, so the posteriors are 1.000000 and 0.000000 and evii equals evpi: 52.0000 on the EKPAN lottery, 35.0000 on the prospect.", "The survey''s cost is zero in both runs, and evii equals evpi whenever information is free on any lottery.", "Both runs quote the likelihood as the posterior, which the engine permits only when a signal is perfect."]'::jsonb, 1, 'The success reading arrives exactly as often as success, 0.350000 on the EKPAN lottery and 0.300000 on perfectSignal, whose evWithInfo is 78.0000, the prospect''s evWithPerfect.'),
  ('decision', 'intermediate', 'final', null, 1, 'An analyst values perfect information on the EKPAN lottery at its 0.350000 prior by repricing the prospect as a certain success, 365.0000 million USD after the drill cost. What is the EVPI, and where did the analyst go wrong?', '["52.0000: the priors stay put, the best value per outcome weights to 127.7500, and EVPI is that less the 75.7500 already available.", "365.0000, since perfect information turns the prospect into a known success and every well it recommends is drilled into a success.", "127.7500, since the value of deciding with the outcome known is itself the worth of the information that makes the deciding possible.", "61.7143, since the EVPI of a two outcome lottery is always read at the switch where Drill and Farm out are worth the same."]'::jsonb, 0, 'Perfect information changes the action, never how often each outcome arrives: the EKPAN lottery is still dry 0.650000 of the time. Read as regret, 0.650000 x 80.0000 = 52.0000.'),
  ('decision', 'intermediate', 'final', null, 2, 'Sampling the EKPAN lottery at round probabilities gives an EVPI of 54.0000 at 0.200000 and 60.0000 at 0.250000, so a reader puts the peak at 0.250000. Where is the peak, and what locates it?', '["At 0.500000, where Success and Dry hole are equally likely and the outcome is hardest to predict, so knowing it in advance is worth the most.", "At 0.228571, where Drill and Farm out are both worth 21.7143 and EVPI reaches 61.7143, because the prior choice is least settled there.", "At 0.250000 as sampled, because EVPI runs straight between tabulated rows and the largest sampled row therefore holds the largest value.", "At 0.179775, where Drill first beats walking away, since below it there is no drilling decision left for perfect information to correct."]'::jsonb, 1, 'Left of 0.228571 perfect information corrects Farm out on a success; right of it, Drill on a dry hole. The two lines meet at the switch, and at 0.500000 EVPI is only 40.0000.'),
  ('decision', 'intermediate', 'final', null, 3, 'The published dominantAction lottery returns emvPrior 65.0000 and evWithPerfect 65.0000. A vendor offers it a survey of accuracy 1.000000. What is that survey worth before its price?', '["65.0000, since a survey that never misreads hands over the whole value of deciding with the outcome known in advance.", "Its full EVPI, which is positive here because Always swings from 100.0000 to 50.0000 and a perfect survey says which one arrives.", "Some amount between 0.0000 and 65.0000 set by the likelihoods, since every informative survey moves the posteriors and so earns value.", "0.0000, because no survey can be worth more than an EVPI of 0.0000, and one action is already best in every outcome."]'::jsonb, 3, '0 <= evii <= evpi. Always pays 100.0000 or 50.0000 against Never''s 10.0000 or 5.0000, so knowing the outcome changes no action and a perfect reading adds nothing.'),
  ('decision', 'intermediate', 'final', null, 4, 'As the CSEM survey''s price on the EKPAN lottery is swept from 0.0000 to 32.0000, a planner expects a dearer survey to show bright spots less readily. What does the sweep do to the chance of a bright spot and to the success posterior after one?', '["Both fall as the price rises, because the tree weights each reading by its net value and a dearer survey leaves less value on the readings.", "The chance of a bright spot holds at 0.460000 while the posterior slides toward the prior 0.350000, since a costlier survey needs stronger evidence.", "Nothing: they stay 0.460000 and 0.646739, since the price is paid before any reading and only the acquire branch moves.", "Both reset to the prior 0.350000 at 28.0000, where the root takes No further information and the readings stop being weighed at all."]'::jsonb, 2, 'pSignal and the posteriors come from the prior and the likelihoods alone. The gross value stays 24.8250 in every row; only the acquire branch and netEvii fall with the price.'),
  ('decision', 'intermediate', 'final', null, 5, 'Working Bayes by hand on the EKPAN lottery, a student divides the joint chance 0.297500 by 0.350000 and lands back on 0.850000. What should the divisor have been?', '["The chance of a dry hole, 0.650000, since a posterior sets a success against the outcome it competes with on the same prospect.", "The chance of a bright spot, 0.460000, which gives a success posterior of 0.646739.", "Nothing at all, since the joint 0.297500 is already the chance of success once a bright spot has been seen on the section.", "The sum of the Bright spot row of likelihoods, since that row gathers every way the same reading can appear across the outcomes."]'::jsonb, 1, 'Dividing a joint by the prior returns the likelihood it came from. 0.297500 / 0.460000 = 0.646739, and 0.353261 of bright spots are still dry holes.'),
  ('decision', 'intermediate', 'final', null, 6, 'A team argues the CSEM survey makes the EKPAN lottery more likely to succeed, because a bright spot lifts success to 0.646739. Averaged over both readings, what happens to the success chance, and where does the survey''s value come from?', '["It rises, since a hit rate of 0.850000 exceeds a false alarm rate of 0.250000, and the survey''s value is that lift in success priced at the Drill payoff.", "It falls, because no bright spot is the commoner reading at 0.540000, and the survey''s value is the share of dry holes it leaves the company better informed about.", "It averages back to 0.350000, since 0.460000 x 0.646739 plus 0.540000 x 0.097222 returns the prior; value comes only from fitting the action to the reading.", "It rises to 0.646739 across the programme, since a company that drills only after a bright spot faces those odds on every well it drills."]'::jsonb, 2, 'A survey moves belief up on one reading and down on the other and nowhere on average. It earns money only where a reading changes what is done.'),
  ('decision', 'intermediate', 'final', null, 7, 'Under No bright spot in the EKPAN lottery''s information tree, the drill chance node reads 18.2639 and the farm-out node 9.2361. Which action is on the optimal path under that reading?', '["Farm out at 9.2361, because the Drill branch is 18.2639 less its 55.0000 cost, -36.7361, and every branch cost comes off before the maximum.", "Drill, since 18.2639 is the larger node and a decision takes the maximum over the values of the nodes it leads to.", "Walk away, since at a posterior of 0.097222 drilling loses money and walking away is the action that avoids any loss.", "Drill, because the 55.0000 cost was settled at the root with the survey and is not charged again under a reading."]'::jsonb, 0, 'A node''s value sits before the cost on the branch into it. Farm out cannot lose money, so it also beats Walk away''s 0.0000.'),
  ('decision', 'intermediate', 'final', null, 8, 'A hand-built information tree for the EKPAN lottery carries 0.350000 and 0.650000 on the outcome branches under both readings. What does that do to the value of acquiring the survey?', '["Nothing, because the reading chances 0.460000 and 0.540000 already carry the survey, so the outcome branches only ever need the priors and 92.5750 survives.", "It overstates the acquisition, since the prior of 0.350000 is above the no-bright-spot posterior of 0.097222 and flatters drilling on that reading.", "It leaves the tree needing the likelihoods 0.850000 and 0.250000 on those branches in place of either the prior or any posterior.", "Every reading then chooses Drill at 75.7500, so the survey adds nothing and the acquire branch is worse than doing without by its cost."]'::jsonb, 3, 'Under a reading the outcome branches must carry that reading''s posteriors, 0.646739 and 0.353261 after a bright spot. With the prior everywhere the reading node returns 75.7500 and the price is pure loss.'),
  ('decision', 'intermediate', 'final', null, 9, 'Before the EC4-0 repair the Analyzer printed a gross value of information of -15.00 on IRRI. Why is a negative value, on its own, evidence of broken inputs?', '["Because the survey cost of 10.0000 had been subtracted from it, and a gross value by definition carries no cost inside it at all.", "Because IRRI''s EVPI is 63.00, and a value below zero is admissible only on a survey that never misreads the outcome it reports.", "Whoever holds a survey can ignore it and take the prior action, so information derived by Bayes is never worth less than 0.", "It is not, since a survey that misleads more often than it informs has a negative value, which the repair now hides from view."]'::jsonb, 2, 'uselessSignal sits on that floor at 0.0000. IRRI''s typed indicators imply success of 0.200000 against 0.300000 stated, and the repaired Analyzer withholds instead.'),
  ('decision', 'intermediate', 'final', null, 10, 'A contractor quotes 40.0000 for the CSEM survey on the EKPAN lottery, pointing out that the price is still under the EVPI of 52.0000. What is the most the survey is worth to this decision?', '["24.8250, its gross value, where the acquire branch falls to the no-information branch at 75.7500.", "52.0000, since EVPI is the ceiling on any survey, so every quote below it leaves some value with the buyer after payment.", "100.5750, the value of deciding after a reading, since any price short of it still leaves the acquire branch above zero.", "16.8250, the net value at a price of 8.0000, since a survey is worth what remains after it has been paid for."]'::jsonb, 0, 'EVPI caps a survey that never misreads, and this one lights up over 0.250000 of dry holes. At 40.0000 the root would choose No further information.'),
  ('decision', 'intermediate', 'final', null, 11, 'Two engine choices on the EKPAN lottery sit at points of indifference: Farm out named at the success probability 0.228571, and Acquire CSEM survey named at a price of 24.8250. What decides each name?', '["The tie rule decides both, since in each case the engine keeps whichever branch was listed first when two values are equal.", "Binary residue decides both, since 24.8250 printed to four decimals hides a last-digit gap between the two root branches as well.", "Neither is a tie: Farm out is worth more at 0.228571 by the printed precision, and at 24.8250 acquiring keeps a positive net value.", "Binary residue decides the first, since Drill less Farm out is -7.11e-15; the tie rule decides the second, where both branches are exactly 75.7500."]'::jsonb, 3, '80 / 350 has no exact binary image, so the choice at the switch is rounding. 100.5750 less 24.8250 is exactly 75.7500, and at an exact tie the first branch listed, the acquisition, is kept.'),
  ('decision', 'intermediate', 'final', null, 12, 'At a survey cost of 32.0000 the EKPAN lottery''s information tree root reads 75.7500, and a reviewer reports the survey as worth 75.7500. What are its gross and net values at that price?', '["Gross 68.5750 and net -7.1750, since the acquire branch at that cost is the survey''s gross value and it falls one for one with the price.", "Gross 24.8250 and net -7.1750; the 75.7500 is the no-information branch, which no price touches.", "Gross and net both -7.1750, because a gross value is recomputed at each quoted price and so falls in step with every rise in the cost.", "Gross 52.0000 and net 20.0000, since a survey is valued at its EVPI ceiling and the quoted price is then taken off that ceiling."]'::jsonb, 1, 'Nothing inside the survey branch responds to the price: pSignal stays 0.460000 and the gross value 24.8250. The root never falls below 75.7500 because declining is always available.'),
  ('decision', 'intermediate', 'final', null, 13, 'At a survey cost of 20.0000 the EKPAN lottery''s information tree acquires with a net value of 4.8250, while the same lottery and survey typed into the Analyzer give a verdict against buying. Which is right for the lottery as described, and why do they part?', '["The Analyzer, because its consistency check caught typed posteriors that the tree engine accepts without question from the likelihoods it is given.", "The tree: the Analyzer can only walk away after no bright spot, so its gross value is 19.8375, short of the cost.", "The Analyzer, since its EMV with Information card is after the survey cost while the tree''s evWithInfo of 100.5750 counts the price twice.", "Both, since they answer at different precision, the Analyzer''s cards rounding to two decimals where the tree carries four of them."]'::jsonb, 1, 'With the farm-out, 0.460000 x 207.7989 + 0.540000 x 9.2361 = 100.5750; without it the second term is 0.0000 and the sum 95.5875. Both tools agree on emvPrior 75.7500 and EVPI 52.0000.'),
  ('decision', 'intermediate', 'final', null, 14, 'A symmetric survey of accuracy 0.600000 on the EKPAN lottery drops the success chance to 0.264151 after a dry reading. What is it worth, and what would make it worth anything?', '["A positive amount in proportion to the move from 0.350000 to 0.264151, since a change of belief is the thing a survey is bought to deliver.", "8.0500, the value the dial reaches as soon as a dry reading lowers the success chance to any point under the prior of 0.350000.", "0.0000; a dry reading has to carry success under the 0.228571 switch so that Farm out replaces Drill, which first happens at accuracy 0.645051.", "0.7250, the first step on the accuracy dial, since every symmetric survey more accurate than a coin buys at least some value."]'::jsonb, 2, 'At 0.600000 both readings still lead to Drill, and Drill is a straight line in p, so the weighted posteriors return 75.7500. Movement that does not cross 0.228571 buys nothing.'),
  ('decision', 'intermediate', 'final', null, 15, 'A symmetric survey of the EKPAN lottery is offered at a cost of 8.0000. Of the tabulated accuracies, which is the lowest at which buying it is justified on EMV grounds?', '["0.645051, since the survey begins to change the action there and a changed action is the thing the price is paid for.", "0.650000, the first tabulated row with a positive gross value, 0.7250, since any positive gross value justifies a purchase.", "0.850000, the accuracy that matches the CSEM survey''s hit rate, below which a symmetric survey cannot compete with that one.", "0.700000, where the gross value 8.0500 first exceeds the cost."]'::jsonb, 3, 'Net is gross less cost: 0.7250 less 8.0000 is negative and 8.0500 less 8.0000 is positive. Changing a choice is necessary for value and not sufficient for a purchase.'),
  ('decision', 'intermediate', 'final', null, 16, 'Midway along the dial between a coin and a perfect reading, a 0.750000 symmetric survey earns the EKPAN lottery 15.3750 against an EVPI of 52.0000. What explains the shortfall from half?', '["Value is zero up to 0.645051 and only then climbs in equal steps to 52.0000, so the halfway accuracy has had little of the climb.", "Because EVPI falls as accuracy rises, so halfway along the dial the ceiling is already lower than 52.0000.", "Because value grows with the square of accuracy, which leaves the halfway point with about a quarter of the EVPI.", "Because the value at 0.750000 is net of an 8.0000 survey cost that the EVPI of 52.0000 does not carry."]'::jsonb, 0, 'EVPI is 52.0000 on every row. The steps 0.7250, 8.0500, 15.3750 are equal because the action after each reading is fixed across those accuracies.'),
  ('decision', 'intermediate', 'final', null, 17, 'Above the flip at 0.645051 the EKPAN lottery''s symmetric-survey values climb on one straight line. Extended back to accuracy 0.600000 that line would go negative. What does the engine return at 0.600000, and why?', '["A negative value on the same line, since the rows climb in equal steps and equal steps run on both sides of 0.645051.", "A refusal, because below the flip the likelihood columns of a symmetric survey can no longer sum to 1 at the accuracy asked for.", "The residue -1.42e-14 at every accuracy under the flip, which the engine returns as the value of a survey that changes nothing.", "0.0000: both readings keep Drill there, so the line no longer describes the policy and value rests on the Bayes floor."]'::jsonb, 3, 'The line assumes Drill after a success reading and Farm out after a dry one. At 0.600000 the weighted Drill values return 75.7500, and information by Bayes is never worth less than 0.'),
  ('decision', 'intermediate', 'final', null, 18, 'The published uselessSignal case and the EKPAN lottery''s symmetric survey at accuracy 0.600000 are both worth 0.0000. What separates the two zeros?', '["Nothing separates them, since a zero value of information means that the readings carry no information about the outcome in either case.", "uselessSignal leaves its posteriors at the priors 0.300000 and 0.700000; the EKPAN lottery''s survey moves success to 0.446809 or 0.264151 and still leaves Drill after both.", "uselessSignal is worth nothing because its prospect''s EVPI is 0.0000, while the EKPAN lottery''s survey is worth nothing because it costs 8.0000.", "The EKPAN lottery''s zero is float residue of -1.42e-14 at every accuracy under 0.645051, while the uselessSignal zero is an exact one."]'::jsonb, 1, 'A useless signal cannot move belief; a worthless one moves it without changing a choice. uselessSignal''s prospect has an EVPI of 35.0000, so its zero belongs to the signal.'),
  ('decision', 'intermediate', 'final', null, 19, 'perfectSignal''s readings leave posteriors of 1.000000 and 0.000000 and an evWithInfo of 78.0000. Which published number must its evii equal?', '["The published prospect''s evpi of 35.0000, since a signal that never misreads turns Bayes into the perfect information table.", "63.0000, the evpi of voiDefaultLottery, since that lottery also reaches an evWithPerfect of 78.0000 and shares the ceiling.", "78.0000 itself, because with certain posteriors the value of deciding with the signal is the value of the signal.", "12.5000, the evii of seismicBayes, because a perfect signal on the same prospect cannot outdo its best real survey."]'::jsonb, 0, 'evWithInfo less evii is 43.0000, the prospect''s emvPrior, so evii is 35.0000. voiDefaultLottery reaches 78.0000 from a baseline of 15.0000, a different decision.'),
  ('decision', 'intermediate', 'final', null, 20, 'The Analyzer''s default study fills four cards: 15.00, 38.00, 23.00 and 63.00. A reader looking for the gross value of the 3D Seismic Survey scans the panel. Where is it, and what is it?', '["23.00 on the Net VOI card, measured against doing nothing.", "38.00 on the EMV with Information card, taken before the cost.", "33.00, in the Decision Guidance sentence and the CSV export; no card carries it.", "63.00 on the EVPI card, since the Analyzer reports its ceiling as the gross value whenever the survey has a cost."]'::jsonb, 2, 'EMV with Information is already after the 10.0000 cost, so 38.00 less 15.00 is the net 23.00; adding the cost back gives 33.00, which is also 48.00 at cost 0 less 15.00.'),
  ('decision', 'intermediate', 'final', null, 21, 'A slide sets the default study''s Net VOI card, 23.00, beside its EVPI card, 63.00, to show how much of perfect information the seismic survey captures. What is the fair comparison?', '["38.00 against 63.00, since EMV with Information is the survey''s gross value and EVPI is the value of perfect information itself.", "23.00 against 63.00 as shown, since both cards come from one engine call.", "Gross against gross, 33.00 against 63.00, because EVPI charges nothing for information.", "33.00 against 78.0000, the value with perfect information, since a gross value belongs beside the gross value of knowing."]'::jsonb, 2, 'The net card has the 10.0000 price inside it and the ceiling does not. EVPI is 78.0000 less 15.0000, the difference of two decision values, so it compares with the gross 33.00.'),
  ('decision', 'intermediate', 'final', null, 22, 'The EKPAN lottery is typed into the Analyzer with Bright spot at 46.000000 percent and No bright spot at 64 percent. What comes back?', '["75.75 and 52.00 only, the rest withheld as for posteriors that contradict the stated chances.", "A full set of cards after the indicator chances are rescaled to 100, with a note that the typed chances were normalised.", "A full set of cards, since indicator chances only weight the readings and an excess shifts the values without breaking them.", "A refusal naming the sum, \"Indicator chances sum to 110 percent, expected 100\", before any card is computed."]'::jsonb, 3, 'Percents that are not a distribution are refused first. Withholding is for percents that are distributions and still imply another prior, as with Bright spot at 56 percent.'),
  ('decision', 'intermediate', 'final', null, 23, 'Typed into the repaired Analyzer, the EKPAN lottery with Bright spot at 56 percent and No bright spot at 44 percent passes the sum check with its posteriors unchanged. What does it report?', '["75.75 and 52.00 only, withholding EMV with Information, both values of information and the diagram.", "Every card, since the indicator chances sum to 100 and the posteriors are the Bayes results carried at full precision.", "Every card, after rescaling the posteriors until implied success returns to 0.350000.", "A gross value of 40.62 marked inconsistent, since the Analyzer prints what it computed beside its consistency warning."]'::jsonb, 0, '56 percent of 64.673913 plus 44 percent of 9.722222 implies success 0.404952, beyond 0.005 of 0.350000. The 40.62 is what the Analyzer printed before the repair.'),
  ('decision', 'intermediate', 'final', null, 24, 'Inverting the EKPAN lottery''s Analyzer entries, Bright spot given Success is 0.646739 x 0.460000 / 0.350000. What does it return, and what does the same arithmetic say with Bright spot typed at 56 percent?', '["0.297500, the joint chance; at 56 percent, a larger joint valued as a stronger survey.", "0.850000, the survey''s hit rate; at 56 percent it exceeds 1, so the typing describes no survey.", "0.646739 unchanged, since inverting only relabels the posterior, and at 56 percent that same posterior with a heavier weight.", "0.850000, and at 56 percent a figure just under 1 marking a very strong survey that the Analyzer still values in full."]'::jsonb, 1, 'The Success column sums to the implied success chance over the stated one, so it sums to 1 only when the typing is consistent. The repaired Analyzer withholds on those 56 percent inputs.'),
  ('decision', 'intermediate', 'final', null, 25, 'On the Analyzer''s default study, what survey price leaves the survey value-neutral, and which number plays the same role on the tree engine''s EKPAN lottery?', '["23.00, the Net VOI card at the default cost, and on the EKPAN lottery its netEvii of 16.8250 at a price of 8.0000.", "63.00, the EVPI card, and on the EKPAN lottery its EVPI of 52.0000, since information turns neutral when priced at its ceiling.", "38.00, the EMV with Information card, and on the EKPAN lottery its acquire branch of 92.5750 at a price of 8.0000.", "33.0000, the gross value found only in the guidance sentence; on the EKPAN lottery, its evii of 24.8250."]'::jsonb, 3, 'At 33.0000 the net card reads 0.00 and the verdict says the information exactly pays for itself; at 24.8250 the EKPAN lottery''s root branches tie at 75.7500. Both prices are gross values, which no card shows.'),
  ('decision', 'intermediate', 'final', null, 26, 'The Analyzer typed with the EKPAN lottery shows EMV without Information 75.75 and EVPI 52.00, exactly the lottery''s own values, and a reviewer signs off the typing on that match. What does the match hide?', '["The missing farm-out, which adds nothing at the prior or with perfect information and shows only in the value with information, 19.84 against 24.8250.", "The survey cost of 8.0000, which both matching values leave out and which the EMV with Information card still has to subtract.", "Nothing, since emvPrior and EVPI bracket the value of information between them, so a match on both pins the survey''s value.", "A rounding gap, since the cards are two-decimal strings and 75.75 conceals the digits that separate the two tools."]'::jsonb, 0, 'After no bright spot the Analyzer can only walk away at 0.0000 where Farm out pays 9.2361, so its value with information is 95.5875 against 100.5750.'),
  ('decision', 'intermediate', 'final', null, 27, 'Squeezing the EKPAN lottery into the Analyzer drops the farm-out, an action the survey would choose after a poor reading. What would change if the action squeezed out were instead the best action at the prior?', '["Nothing further, since a missing action always understates the value of information by its weighted value after the reading that uses it.", "EVPI would expose it at once, since EVPI is computed over every action the decision really has, whatever the form offers.", "EMV without information would be wrong as well, so the value of information could err in either direction.", "The consistency check would withhold the value, since typed posteriors cannot agree with a prior valued on the wrong actions."]'::jsonb, 2, 'On the EKPAN lottery Drill at 75.7500 beats Farm out at 33.2500, so emvPrior and EVPI survive the omission and only the value with information exposes it, 95.5875 against 100.5750.'),
  ('decision', 'intermediate', 'final', null, 28, 'The CSEM survey''s hit rate, 0.850000, is typed into the Analyzer as P(Success | Bright spot) for the EKPAN lottery. How does the repaired Analyzer''s response differ from a hand rollback that makes the same misreading?', '["Both overvalue the survey by the same amount, since the Analyzer and the rollback run the same Bayes arithmetic on the number typed.", "The rollback values Drill after a bright spot at 298.2500 against 207.7989; the Analyzer finds the implied success chance far from 0.350000 and withholds.", "The Analyzer refuses with a message naming the sum, since a success chance of 0.850000 cannot sit in a row that also holds a dry hole.", "The Analyzer converts 0.850000 into the posterior 0.646739 first, because it inverts every typed entry back to likelihoods before valuing."]'::jsonb, 1, 'The Analyzer never inverts and never rescales; the row still sums to 100, so it is withheld and not refused. The hand overstatement lands on the reading that argues for drilling.'),
  ('decision', 'intermediate', 'final', null, 29, 'On IRRI both indicators are typed 20 / 80 percent against a stated Success Case of 30 percent. Which two values does the repaired Analyzer still print, and why can it?', '["15.00 and -15.00, the value at the prior and a gross value of information now shown beside a consistency warning.", "63.00 alone, since EMV without information uses the implied 0.200000.", "None, since typed percents that contradict each other are refused with a message naming the sum in percent.", "15.00 and 63.00, since EMV without information and EVPI use only the stated outcome chances."]'::jsonb, 3, 'The indicators imply success of 0.200000 against 0.300000, far beyond the 0.005 tolerance, so every value that needs the posteriors is withheld. The -15.00 is pre-repair history.'),
  ('decision', 'intermediate', 'final', null, 30, 'Before the EC4-0 repair, a posterior row summing to 130 percent printed a gross value of information of 69.00 beside an EVPI card of 63.00. Which bound did that break, and what does the repaired Analyzer do with the input?', '["The upper bound, since no information is worth more than knowing the outcome; the row is now refused with a message naming 130 percent.", "The lower bound, since a gross value above EVPI turns negative once the survey cost is charged, and the input is now withheld.", "No bound, since EVPI is a card after cost and the gross value before it, and the repaired Analyzer prints both unchanged.", "The upper bound, and the repaired Analyzer now rescales the row to 100 percent and prints a value under 63.00."]'::jsonb, 0, '0 <= value <= EVPI for any information derived by Bayes. A row that is not a distribution is refused before any card; withholding is for distributions that contradict the stated chances.'),
  ('decision', 'intermediate', 'final', null, 31, 'A capstone answer subtracts the EKPAN tree''s drill branch value, 105.0000, from the EKPAN lottery''s evWithPerfect, 127.7500, to get EVPI. What is wrong?', '["Nothing, since the EKPAN tree and lottery share one prospect at a 0.350000 success chance, and EVPI needs only the best prior value.", "The baseline should be the lottery''s farm-out at 33.2500, since perfect information recommends the farm-out on a dry hole.", "It mixes two models: the lottery''s baseline is its own emvPrior of 75.7500, giving 52.0000, while 105.0000 belongs to the three-outcome tree.", "The subtraction runs backwards, since EVPI is the value at the prior less the value with perfect information."]'::jsonb, 2, 'The EKPAN tree''s drill branch of 105.0000 loses money with probability 0.500000; the EKPAN lottery''s drill action of 75.7500 loses with probability 0.650000. Section 16 carries them as separate fields.'),
  ('decision', 'intermediate', 'final', null, 32, 'On a known dry hole in the EKPAN lottery, Farm out and Walk away both pay 0.0000 and the table names Farm out. If Walk away were listed first, what would happen to EVPI?', '["EVPI would fall, because naming Walk away gives up the farm-out''s 95.0000 on a success that perfect information could still reveal.", "Only the name changes: EVPI stays 52.0000, since it takes the best value per outcome.", "It rises to 61.7143, as the farm-out line no longer sets the switch.", "The engine refuses: a tie on one outcome leaves the best action undefined."]'::jsonb, 1, 'The best value on a dry hole is 0.0000 whichever action is named. A tie on an outcome row is the first-branch rule at work, and it moves labels, never values.'),
  ('decision', 'intermediate', 'final', null, 33, 'The CSEM survey on the EKPAN lottery is worth 24.8250, between the symmetric survey''s 22.7000 at accuracy 0.800000 and 30.0250 at 0.850000. Why can no symmetric survey, at any accuracy, pass 52.0000?', '["At accuracy 1.000000 Bayes becomes the perfect information table, and the lottery fixes EVPI at 52.0000 whatever the survey.", "Because the engine clamps each evii at the EVPI and reports the clamp whenever a survey would otherwise exceed the ceiling.", "Because EVPI is recomputed at each accuracy and falls toward the survey''s own value as the survey improves on the dial.", "Because a symmetric survey is right about a dry hole only as often as about a success, which holds it under the CSEM survey''s 0.750000."]'::jsonb, 0, 'At accuracy 1.000000, 0.350000 x 365.0000 = 127.7500 and evii is 52.0000. The bound is arithmetic and no clamp: every posterior is derived from one prior.'),
  ('decision', 'intermediate', 'final', null, 34, 'With the CSEM survey on the EKPAN lottery, which reading earns the survey''s whole value over the prior action, and why?', '["Bright spot: it lifts success to 0.646739 and carries Drill to 207.7989, far above the prior value of 75.7500.", "Both readings, in proportion to their chances of 0.460000 and 0.540000, since each moves the posterior away from the prior.", "Neither alone: value is the gap between the posteriors 0.646739 and 0.097222, priced at Drill''s net payoff of 365.0000.", "No bright spot: its posterior 0.097222 falls under the 0.228571 switch, and Farm out at 9.2361 replaces Drill at -36.7361."]'::jsonb, 3, 'Drill is already best at the prior, so a reading that keeps Drill earns nothing over it. The gain after no bright spot, weighted by 0.540000, is the whole 24.8250.'),
  ('decision', 'intermediate', 'final', null, 35, 'A symmetric survey of accuracy 0.700000 is worth 8.0500 on the EKPAN lottery. Squeezed into the Analyzer''s two actions, drill or Do Not, with its posteriors typed consistently, what is it worth?', '["8.0500, since the posteriors after each reading are the same in either tool, and the value of a survey comes from its posteriors.", "0.0000: a dry reading leaves success at 0.187500, still above the drill against walk-away switch of 0.179775, so Drill follows both readings.", "Less than 8.0500 but positive, short by the farm-out''s value after a dry reading weighted by that reading''s chance, as on the CSEM survey.", "Nothing it can print, since typing a symmetric survey''s posteriors into a two-action form contradicts the stated outcome chances and is withheld."]'::jsonb, 1, 'Without the farm-out the action after a dry reading turns only below 80 / 445 = 0.179775. The 0.750000 row, carrying success to 0.152174, is the first tabulated accuracy that would change the two-action choice.'),
  ('decision', 'intermediate', 'final', null, 36, 'A budget paper says the CSEM survey on the EKPAN lottery is worth 92.5750 at a price of 8.0000. What has it actually reported?', '["The survey''s gross value, since 92.5750 is the reading chance node before any price has been charged.", "The survey''s net value, since the price of 8.0000 has already come off the value with information.", "The value with perfect information less the price, the most a survey that never misread could return.", "The acquire branch, the whole decision with the survey bought; the survey''s own contribution is 16.8250."]'::jsonb, 3, '100.5750 less 8.0000 is 92.5750, and against 75.7500 without the survey the difference, 16.8250, is netEvii. The gross 24.8250 is the neutral price.'),
  ('decision', 'intermediate', 'final', null, 37, 'On the published seismic prospect, seismicCost5''s root reads 50.5000 with bestBranchIndex 0 and seismicCost20''s reads 43.0000 with bestBranchIndex 1. What value with information do the two share, and where does the root flip?', '["50.5000, the acquire branch at the cheaper price, with the flip at 7.5000, the net value seismicBayes records for its survey.", "43.0000, since that is the root both share once the price rises, with the flip at 20.0000 where the branch index changes.", "55.5000 before the price; the root flips once the price passes the gross value 12.5000, where costExactlyNetZero ties at 43.0000.", "78.0000, the value with perfect information on that prospect, with the flip at its EVPI of 35.0000 on every quote."]'::jsonb, 2, 'Each acquire branch is 55.5000 less the price, 50.5000 at 5.0000 and 35.5000 at 20.0000, against 43.0000 without the survey. At 12.5000 the tie keeps the acquisition, listed first.'),
  ('decision', 'intermediate', 'final', null, 38, 'The Analyzer shows EMV with Information 87.59 for the EKPAN lottery, while the tree engine''s evWithInfo is 100.5750. What separates the two?', '["Only the survey cost, since 100.5750 less 8.0000 is the card value once the card has been rounded to two decimals.", "Only the missing farm-out, since both numbers are values before the survey cost is charged on the acquire branch.", "The card is after the 8.0000 cost, and the Analyzer has no farm-out, so even with the cost added back it reaches only 95.5875.", "The consistency check, which trims the Analyzer''s value whenever its posteriors are typed to six decimals and the tree engine''s posteriors are not."]'::jsonb, 2, '95.5875 less 8.0000 is 87.5875, the drawn tree''s root. The tree engine''s own acquire branch after the same cost is 92.5750.'),
  ('decision', 'intermediate', 'final', null, 39, 'A survey is entered in the tree engine with likelihoods over Success of 0.850000 for a bright spot and 0.050000 for none. What does the engine do?', '["It rescales the Success column to sum to 1 and values the survey on the normalised likelihoods without comment.", "It refuses: \"Likelihoods P(signal | \"Success\") sum to 0.900000, expected 1\", and values nothing.", "It treats the missing 0.100000 as a reading that never arrives and values the rest.", "It values the survey, since only the chances of the signals across both outcomes are required to sum to 1."]'::jsonb, 1, 'Each outcome''s column is a distribution over readings and must sum to 1 within 1e-6. The engine refuses and never quietly normalises.'),
  ('decision', 'intermediate', 'final', null, 40, 'If the geologist''s success estimate on the EKPAN lottery moved from 0.350000 to 0.900000, with the CSEM survey''s likelihoods unchanged, what happens to the ceiling on that survey''s value?', '["It falls to an EVPI of 8.0000, because Drill is then rarely wrong and perfect information corrects it only on the rare dry hole.", "It stays at 52.0000, since EVPI belongs to the payoffs and to the survey, and neither of those has moved with the estimate.", "It rises to 328.5000, the value with perfect information at 0.900000, since the prospect itself is now worth much more.", "It rises toward the peak of 61.7143, since a likelier success makes the outcome more certain and so makes any information about it more decisive."]'::jsonb, 0, 'EVPI at 0.900000 is 328.5000 less 320.5000. The likelihoods 0.850000 and 0.250000 have not moved, but no survey on that decision can be worth more than 8.0000.'),
  ('decision', 'intermediate', 'final', null, 41, 'At a survey cost of 50.0000 on the Analyzer''s default study, the EMV with Information card reads -2.00, and a reader concludes the well itself has turned into a loss. What does the Analyzer actually say?', '["That drilling has turned negative, since EMV with Information is the value of the drill decision once the survey result is known.", "That the survey is still justified, since its gross value of 33.00 stays positive and the verdict sentence reads the gross value.", "Nothing further: a card below zero means contradictory chances, so the rest is withheld.", "Net VOI -17.00 and a verdict against buying the survey; the drawn tree''s root takes No further information."]'::jsonb, 3, 'The card is after the cost: 48.00 less 50.0000 is -2.00, and -2.00 less 15.00 is -17.00. A negative card here reflects a price and no broken input.'),
  ('decision', 'intermediate', 'final', null, 42, 'The Analyzer holds back a value of information when its typed numbers disagree. What keeps an information tree built from likelihoods from ever reaching that state?', '["It takes likelihoods and derives every posterior from the one stated prior, so its inputs cannot imply a different prior.", "It rounds every posterior to six decimals before valuing, which keeps any implied prior inside the 0.005 tolerance.", "It checks consistency as well, but it repairs a gap by rescaling the posteriors where the Analyzer withholds.", "It values only surveys with a positive EVPI, so an inconsistent survey is refused by the engine at the door before anything could be withheld."]'::jsonb, 0, 'The Analyzer takes typed posteriors, which can carry a prior of their own, as IRRI''s 0.200000 against 0.300000 shows. The engine''s 0.460000 x 0.646739 plus 0.540000 x 0.097222 always returns 0.350000.');
